window.KG_WEEKEND = [{"id": 1, "date": "2026-10-03", "range": "9/27 – 10/3", "title": "第 1 期周末测试 · 本周串考", "sub": "覆盖本周 5 期考公 + 30 个成语 + 40 道速算 + 3 期新闻，含下周拓展", "note": "行测 13 题交卷自动判分；申论 2 题交卷后对照踩分点自评。做题过程中不给答案、不给解析。", "xz": [{"no": 1, "mod": "常识判断", "from": "第 1 期 · 马原唯物论", "type": "single", "stem": "有观点认为：既然量子计算、基因编辑等技术不断突破，「人的意识可以直接创造物质」。这一观点（　）", "options": ["正确，因为意识活动具有目的性和计划性", "正确，因为科技进步使意识的作用越来越大", "错误，意识只有通过实践才能把观念的东西变成现实", "错误，因为物质与意识之间没有联系"], "answer": ["C"], "explain": "意识具有能动作用（A、B 都夸大了这一点），但「直接现实性」是实践的特点，意识本身不能直接创造物质，必须通过实践把观念的东西变成现实，故 C 正确。D 否认了物质与意识的辩证联系，意识是物质世界长期发展的产物。", "tip": "见「直接现实性」就排除（那是实践的特点）；「意识创造物质」「意识决定物质」一律判错。", "key": "物质决定意识，意识有能动反作用，但必须通过实践才能改变现实。"}, {"no": 2, "mod": "常识判断", "from": "第 2 期 · 马原辩证法", "type": "single", "stem": "「我们既要看到合作带来的机遇，也要清醒认识其中的风险挑战，做到斗而不破、以斗促合。」这一判断最能体现的哲学道理是（　）", "options": ["主要矛盾决定事物的性质", "矛盾双方既对立又统一，在一定条件下相互转化", "矛盾的普遍性寓于特殊性之中", "质变是量变的必然结果"], "answer": ["B"], "explain": "「机遇与风险并存」「斗而不破、以斗促合」体现的是矛盾双方的对立统一（同一性与斗争性），故 B 正确。A 把主要矛盾与矛盾的主要方面混淆了；C、D 与题意无关。", "tip": "材料出现「既…又…」「相互依存/相互转化」→ 优先选对立统一（矛盾双方）。", "key": "矛盾双方既对立又统一，条件具备可相互转化。"}, {"no": 3, "mod": "常识判断", "from": "第 3 期 · 马原认识论", "type": "multi", "stem": "关于真理的绝对性与相对性，下列说法正确的有（　）【多选】", "options": ["真理的绝对性是指真理主客观统一的确定性和发展的无限性", "真理的相对性是指人们在一定条件下对客观事物及其规律的正确认识总是有限度的", "任何真理都是绝对性和相对性的统一", "真理的相对性说明真理当中包含谬误"], "answer": ["A", "B", "C"], "explain": "A、B、C 都是基本原理。D 错误：真理的相对性是指认识的广度和深度有待扩展深化，并非真理中包含谬误——真理与谬误有原则界限。", "tip": "「真理包含谬误」「真理与谬误没有界限」必错；相对性＝有待发展的正确认识。", "key": "绝对性＝确定性与无限发展；相对性＝有条件、有待深化；二者统一。"}, {"no": 4, "mod": "常识判断", "from": "第 1、5 期 · 毛概/党史", "type": "single", "stem": "毛泽东把「统一战线、武装斗争、党的建设」称为战胜敌人的三大法宝，其中居于中心地位、起决定性作用的是（　）", "options": ["统一战线", "武装斗争", "党的建设", "群众路线"], "answer": ["C"], "explain": "三大法宝中党的建设是中心环节——统一战线和武装斗争都要靠党的领导来掌握。群众路线是党的根本工作路线，不属于三大法宝。", "tip": "三大法宝的「中心环节」＝党的建设；易错选「统一战线」。", "key": "三大法宝＝统一战线·武装斗争·党的建设，党的建设是中心环节。"}, {"no": 5, "mod": "常识判断", "from": "第 1、3 期 · 习思想", "type": "single", "stem": "多地推进「人工智能＋政务服务」改革，把群众办事从「最多跑一次」推向「一次都不用跑」。这最直接体现的是（　）", "options": ["全过程人民民主的本质要求", "以人民为中心的发展思想", "共同富裕的奋斗目标", "总体国家安全观"], "answer": ["B"], "explain": "政务服务改革以方便群众为出发点和落脚点，直接体现以人民为中心的发展思想。A 强调民主环节的广泛性（选举、协商、决策、管理、监督）；C 侧重分配与差距；D 侧重安全。", "tip": "「便民、办实事、群众获得感」→ 以人民为中心；「协商、投票、监督」→ 全过程人民民主。", "key": "以人民为中心＝便民改革类题目的首选答案。"}, {"no": 6, "mod": "常识判断", "from": "第 5 期 · 民法典（拓展）", "type": "single", "stem": "甲公司在其官网发布「新款手机 1999 元/台，欢迎下单」的商品信息。根据民法典，该商品信息一般应认定为（　）", "options": ["要约", "要约邀请", "承诺", "合同已经成立"], "answer": ["B"], "explain": "面向不特定人发布、未表明「一经承诺即受约束」的商业宣传，一般视为要约邀请（B）。若内容具体确定且表明经受要约人承诺即受约束，才构成要约（A）。承诺是受要约人同意要约的意思表示；合同成立还需承诺生效，D 错。", "tip": "招标公告、拍卖公告、招股说明书、商业广告多为要约邀请；「符合要约条件」的才例外。", "key": "商业广告一般是要约邀请，符合条件才构成要约。"}, {"no": 7, "mod": "常识判断", "from": "第 5 期 · 经济指标", "type": "single", "stem": "下列关于常用经济指标的表述，正确的是（　）", "options": ["恩格尔系数越大，说明居民生活水平越高", "CPI 持续大幅上涨通常意味着通货膨胀压力加大", "GDP 是衡量居民收入分配差距的核心指标", "基尼系数越小，说明收入分配差距越大"], "answer": ["B"], "explain": "CPI 是居民消费价格指数，持续大幅上涨反映通胀压力，B 正确。A 错：恩格尔系数（食品支出占消费总支出比重）越大说明生活水平越低。C 错：衡量分配差距的是基尼系数。D 错：基尼系数越小，差距越小。", "tip": "恩格尔系数、基尼系数都是「越大越差」（一个生活水平低，一个分配差距大），方向别记反。", "key": "CPI↑＝通胀压力；恩格尔系数与基尼系数越大越差。"}, {"no": 8, "mod": "常识判断", "from": "第 5 期 · 科技成就", "type": "single", "stem": "关于我国近年重大科技成就，下列对应正确的是（　）", "options": ["墨子号——量子保密通信领域的量子科学实验卫星", "九章——深海载人潜水器", "奋斗者号——火星探测器", "中国空间站——以「天问」命名"], "answer": ["A"], "explain": "墨子号是量子科学实验卫星（A 正确）。九章是量子计算原型机（B 错）；奋斗者号是深海载人潜水器，火星探测器是天问一号（C 错）；空间站由天和核心舱与问天、梦天实验舱组成（D 错）。", "tip": "深潜＝蛟龙/深海勇士/奋斗者；火星＝天问一号；量子计算＝九章；量子通信卫星＝墨子号；空间站＝天和/问天/梦天。", "key": "墨子号＝量子卫星，九章＝量子计算，奋斗者＝深潜，天问＝火星。"}, {"no": 9, "mod": "言语理解与表达", "from": "本周成语 · 第 1、3 期", "type": "single", "stem": "下列句子中加点成语使用恰当的一项是（　）", "options": ["这部纪录片播出后迅速炙手可热，街头巷尾都在讨论", "这篇社论见解精辟，被学界视为不刊之论", "面对突发灾情，消防员首当其冲冲在救援最前线", "晚会现场美轮美奂的歌声，赢得观众阵阵掌声"], "answer": ["B"], "explain": "「不刊之论」指不可改动或磨灭的言论（刊＝削除、修改），用来评价见解精辟的社论，恰当（B）。A 错：「炙手可热」含贬义，形容气焰盛、权势大，不能形容作品走红（应为「不胫而走」）。C 错：「首当其冲」指最先受到冲击或遭遇灾难，不是「冲在最前面」。D 错：「美轮美奂」形容房屋建筑高大华丽，不能修饰歌声。", "tip": "成语题先看两件事：对象（人/物/建筑/声音）＋褒贬色彩。炙手可热（贬义·权势）、首当其冲（最先受冲击）、美轮美奂（建筑）、差强人意（大体满意）、空穴来风（有来由）。", "key": "判断成语先看「适用对象＋感情色彩」。"}, {"no": 10, "mod": "言语理解与表达", "from": "本周成语 · 第 3 期", "type": "single", "stem": "依次填入下列两句横线处的成语，最恰当的一项是（　）\n①这位年轻球员在决赛中连入两球，_____，成为全场焦点。\n②他的方案脱离实际、漏洞百出，最终_____，被评审组否决。", "options": ["不负众望 / 不孚众望", "不孚众望 / 不负众望", "不负众望 / 不负众望", "不孚众望 / 不孚众望"], "answer": ["A"], "explain": "「不负众望」＝不辜负大家的期望，含褒义，适合①的正面语境；「不孚众望」＝不能使大家信服（孚＝使人信服），适合②的负面语境。两词一字之差、感情色彩完全相反。", "tip": "负＝辜负（不负众望＝好）；孚＝信服（不孚众望＝差）。同类：「不胫而走」是消息传播快，不含「没有腿」的字面义。", "key": "不负众望（好）／不孚众望（差）。"}, {"no": 11, "mod": "判断推理", "from": "拓展 · 定义判断", "type": "single", "stem": "凡勃伦效应是指消费者对某种商品的需求程度因其标价较高（而不是较低）而增加。根据上述定义，下列属于凡勃伦效应的是（　）", "options": ["某品牌手机降价促销后，销量明显上升", "某奢侈品牌手袋涨价后，反而有更多消费者排队购买", "某超市推出买一送一活动，客流量大幅增加", "某电商平台通过直播折扣，单品销量翻倍"], "answer": ["B"], "explain": "凡勃伦效应的关键是「价格越高、需求越大」——涨价反而引来更多购买，B 符合定义。A、C、D 都是「降价或优惠带来销量上升」，属于一般的价格与需求关系，与定义正好相反。", "tip": "定义判断先抓关键词：凡勃伦效应＝越贵越买（炫耀性消费）。凡是「降价→销量上升」的选项一律排除。", "key": "越贵越买＝凡勃伦效应（炫耀性消费）。"}, {"no": 12, "mod": "数量关系", "from": "速算 · 连续变化", "type": "single", "stem": "某商品先涨价 20%，后因促销降价 10%，则最终售价与原价相比（　）", "options": ["上涨 8%", "上涨 10%", "下降 2%", "没有变化"], "answer": ["A"], "explain": "连续变化要用乘法：1×(1＋20%)×(1－10%)＝1×1.2×0.9＝1.08，即上涨 8%。绝不能用加减法（20%－10%＝10%）直接算。", "tip": "速算口诀：连续涨跌用连乘。1.2×0.9＝1.08，几秒钟出结果。", "key": "连续涨跌 → 连乘，不能加减。"}, {"no": 13, "mod": "资料分析", "from": "速算 · 两期比重差（拓展）", "type": "single", "stem": "2026 年上半年，该市新能源汽车产量占全市汽车总产量的比重，与上年同期相比约（　）", "data": "2026 年上半年，某市汽车总产量 98.4 万辆，同比增长 5%；其中新能源汽车产量 24.6 万辆，同比增长 20%。", "options": ["上升约 3 个百分点", "上升约 1 个百分点", "下降约 1 个百分点", "基本不变"], "answer": ["A"], "explain": "先判断升降：部分增速（20%）＞整体增速（5%），比重上升，排除 C、D。再算幅度：现期比重＝24.6÷98.4＝25%；基期比重＝(24.6÷1.2)÷(98.4÷1.05)≈20.5÷93.7≈21.9%；两者相差约 3.1 个百分点，故选 A。", "tip": "两期比重差速算：①比增速定方向（部分>整体则升）；②幅度远小于增速差（15 个百分点差，实际只有 3 个百分点），估个位数即可。", "key": "部分增速＞整体增速 → 比重上升，幅度远小于增速差。"}], "sl": [{"no": 1, "mod": "归纳概括", "from": "本周新闻 · 国企协同/产业链 + 拓展", "stem": "材料一：2026 年 9 月，中国一汽与广汽集团签署战略合作框架协议，双方以资本资产联动为抓手的央地国企市场化协同，推动南北丰田开启协同运营，在整车平台、技术研发、供应链体系上实现资源共享。\n材料二：工信部《智能网联新能源汽车产业发展规划》明确提出鼓励企业通过兼并重组提升产业集中度；2025 年 7 月中央财经委会议强调依法治理低价无序竞争。\n材料三：某省围绕新能源汽车产业链组建「链主企业＋专精特新」配套体系，中小企业接入共享平台后，采购成本平均下降 8%，产品交付周期缩短 20%，多家配套企业从「单打独斗」转为「抱团出海」。", "req": "根据给定材料，概括我国推动产业协同发展采取的主要举措。", "limit": "不超过 200 字", "points": [{"pt": "推动央地国企跨区域、跨所有制资本协同，以股权资产联动方式整合整车与产业资源", "n": 3}, {"pt": "强化政策引导，鼓励兼并重组、提升产业集中度，依法治理低价无序竞争", "n": 2}, {"pt": "构建「链主企业＋专精特新」产业链配套体系，带动中小企业协同发展", "n": 3}, {"pt": "搭建共享平台，实现技术、供应链、市场等资源互通共用，降本增效、抱团出海", "n": 2}], "sample": "一是推动国企跨区域、跨所有制资本协同，以股权资产联动整合整车资源（3 分）；二是强化政策引导，鼓励兼并重组提升产业集中度，依法治理低价无序竞争（2 分）；三是构建「链主企业＋专精特新」配套体系，带动中小企业协同发展（3 分）；四是搭建共享平台，推动技术、供应链与市场资源互通，实现降本增效、抱团出海（2 分）。", "tip": "归纳概括三步走：①逐段提炼「谁＋做了什么＋达到什么效果」；②按「国企改革／政策引导／产业链机制／平台共享」分层，一条一句；③字数用足九成左右，只概括不评论、不抄长句。踩分点基本等于「材料每段的核心做法」各一条。"}, {"no": 2, "mod": "申论大作文", "from": "本周新闻 + 金句（合作共赢/协同治理）", "stem": "「合则两利、斗则俱伤是历史启示，相互成就、合作共赢是唯一正确选择。」请结合给定材料和自身体会，以「协同」为主题，自拟题目，写一篇文章。", "req": "自选角度，自拟标题；观点明确，结构完整，语言流畅；结合材料但不拘泥于材料；800～1000 字。", "limit": "800～1000 字", "points": [{"pt": "立意准确：围绕「协同／合作共赢」立论，并能上升到高质量发展、治理现代化层面", "n": 4}, {"pt": "结构完整：标题点题、开头破题、2～3 个分论点、结尾升华，层次清晰", "n": 4}, {"pt": "论据充实：能举出产业协同（南北丰田整合）、区域协同（超大规模市场）、治理协同（AI 治理、安全与发展并重）、生态协同（保护—修复—价值转化）等具体例证", "n": 8}, {"pt": "语言与规范：有排比或对仗句式，用上本周金句素材，字数达标、卷面整洁", "n": 4}], "sample": "【参考框架】\n标题：以协同之笔，写共赢之篇\n分论点一：产业协同，向存量整合要效率——一汽与广汽的资本联动，南北丰田共享平台与供应链，把「两套人马」变成「一套体系」。\n分论点二：区域协同，向超大规模市场要空间——近 2 亿人次跨区域流动、黄岩岛常态化巡航，印证「不靠一时一事的高调，而靠日复一日的在场」。\n分论点三：治理协同，向发展与安全的平衡要定力——AI 模型按下暂停键、联合国谈判弱化安全条款，说明「技术跑得越快，治理越不能掉队」。\n开头示范：合则两利、斗则俱伤，是历史给出的启示；相互成就、合作共赢，是时代给出的选择。从产业到区域，从治理到生态，协同正在成为破解难题的通用钥匙。\n结尾示范：护绿是让荒山重新长出树，复绿是让断流的河重新淌起水，用绿是让守着青山的人也能过上好日子。一花独放不是春，万紫千红春满园——唯有以协同为笔、以共赢为墨，方能书写高质量发展的新篇章。", "tip": "大作文五招：①标题「动词＋主题＋价值」（以…之笔，写…之篇）；②三个分论点句式对齐（都以「向…要…」收尾）；③每段「观点句＋例证＋回扣」三段式；④结尾「回望—当下—未来」或排比收束；⑤留足 5 分钟写结尾、当场数字数。"}]}, {"id": 2, "date": "2026-10-03", "range": "9/28 – 10/3", "title": "第 2 期周末测试 · 本周串考", "sub": "覆盖本周 010–013 期考公 + 本周成语 + 速算技巧 + 新闻素材（含下周拓展）", "note": "行测 13 题交卷自动判分；申论 2 题交卷后对照踩分点自评。做题过程中不给答案、不给解析。", "xz": [{"no": 1, "mod": "常识判断", "from": "第 11 期 · 马原（内容与形式）", "type": "single", "stem": "关于内容与形式的关系，下列说法正确的是（　）", "options": ["内容决定形式，形式对内容没有任何影响", "内容决定形式，形式反过来影响并制约内容", "形式决定内容，内容服务于形式", "内容与形式彼此独立、互不相干"], "answer": ["B"], "explain": "内容与形式是对立统一的：内容决定形式，形式必须适合内容；同时形式具有相对独立性，会反过来影响、制约内容。A 否认了形式的反作用；C 颠倒了决定关系；D 割裂了二者联系。", "tip": "记口诀“内容定形式、形式反作用”；凡“形式决定内容”一律判错。", "key": "内容决定形式，形式反作用于内容。"}, {"no": 2, "mod": "常识判断", "from": "第 11 期 · 马原（生产力）", "type": "single", "stem": "在社会发展中起最终决定作用的力量是（　）", "options": ["生产关系", "生产力", "上层建筑", "地理环境"], "answer": ["B"], "explain": "生产力是社会发展的最终决定力量，它决定生产关系，进而决定上层建筑。A、C 都受生产力决定；D 是影响因素而非最终决定力量。", "tip": "看到“最终决定力量”直接选生产力；生产力→生产关系→上层建筑是因果链。", "key": "生产力是社会发展的最终决定力量。"}, {"no": 3, "mod": "常识判断", "from": "第 12 期 · 毛概（活的灵魂）", "type": "multi", "stem": "毛泽东思想活的灵魂包括（　）【多选】", "options": ["实事求是", "群众路线", "独立自主", "武装斗争"], "answer": ["A", "B", "C"], "explain": "活的灵魂＝实事求是、群众路线、独立自主三个方面，故选 A、B、C。D 错：“武装斗争”是新民主主义革命三大法宝之一（另两个是统一战线、党的建设），不属于“活的灵魂”。", "tip": "区分两组概念：三大法宝＝统一战线·武装斗争·党的建设；活的灵魂＝实事求是·群众路线·独立自主。", "key": "活的灵魂＝实事求是·群众路线·独立自主。"}, {"no": 4, "mod": "常识判断", "from": "第 12 期 · 党史（十五大）", "type": "single", "stem": "把邓小平理论确立为党的指导思想并写入党章的是（　）", "options": ["中共十三大", "中共十四大", "中共十五大", "中共十六大"], "answer": ["C"], "explain": "1997 年中共十五大把邓小平理论确立为党的指导思想并写入党章。十三大系统阐述初级阶段理论，十四大明确社会主义市场经济体制目标，十六大写入“三个代表”。", "tip": "记对应：十五大→邓小平理论，十六大→三个代表，十八大→科学发展观。", "key": "十五大→邓小平理论写入党章。"}, {"no": 5, "mod": "常识判断", "from": "第 12 期 · 中特（核心价值观）", "type": "single", "stem": "社会主义核心价值观中，属于国家层面价值目标的是（　）", "options": ["富强、民主、文明、和谐", "自由、平等、公正、法治", "爱国、敬业、诚信、友善", "民主、自由、平等、博爱"], "answer": ["A"], "explain": "核心价值观分三个层面：国家层面＝富强、民主、文明、和谐；社会层面＝自由、平等、公正、法治；个人层面＝爱国、敬业、诚信、友善。故选 A。", "tip": "口诀“国家富强、社会自由、个人爱国”对应三个层面，别串层。", "key": "国家层面＝富强·民主·文明·和谐。"}, {"no": 6, "mod": "常识判断", "from": "第 12 期 · 法律（国家结构）", "type": "single", "stem": "我国的国家结构形式是（　）", "options": ["单一制", "联邦制", "邦联制", "复合制"], "answer": ["A"], "explain": "我国是典型的单一制国家：有统一的宪法和中央政权，地方接受中央统一领导，同时实行民族区域自治和特别行政区制度。B、C、D 均为复合制或与我国不符。", "tip": "“单一制”不等于“没有自治”——民族区域自治、特别行政区都是单一制下的特殊安排。", "key": "我国是单一制国家。"}, {"no": 7, "mod": "言语理解与表达", "from": "本周成语（第 011 / 012 期）", "type": "single", "stem": "下列句子中，成语使用恰当的一项是（　）", "options": ["公司资金链紧绷，每到月底便捉襟见肘，连工资都要东拼西凑。", "这次活动准备充分，取得成功可以说是七月流火。", "他对工作一向首鼠两端，认真细致。", "得知失联者全部获救，家属们弹冠相庆。"], "answer": ["A"], "explain": "A 恰当：“捉襟见肘”指顾此失彼、不够用，与“资金紧绷、凑工资”吻合。B 误用：“七月流火”指天气转凉，不表“热烈成功”。C 误用：“首鼠两端”指犹豫动摇，与“认真细致”矛盾。D 误用：“弹冠相庆”含贬义（小人得意），家属获喜讯应用“额手称庆”。", "tip": "成语题先判“褒贬+适用对象”：望文生义（七月流火）、褒贬反用（弹冠相庆）是两大高频陷阱。", "key": "捉襟见肘＝拮据窘迫；七月流火＝转凉；首鼠两端＝动摇；额手称庆≠弹冠相庆。"}, {"no": 8, "mod": "言语理解与表达", "from": "本周新闻（科技自立自强）", "type": "single", "stem": "智驾技术在真实道路上积累的里程，既是数据，也是信任。算法只有在足够多样的场景里反复试错，才能把“能用”变成“好用”。这提示我们，核心技术的突破，不能只寄望于实验室里的灵光一现。\n这段文字意在说明（　）", "options": ["智能驾驶已经完全可以取代人工驾驶", "核心技术的成熟离不开真实场景中的持续积累", "数据越多，算法就必然越安全", "实验室研究对技术突破没有意义"], "answer": ["B"], "explain": "文段由智驾里程切入，落脚在“核心技术突破不能只靠实验室灵光一现”，即强调真实场景持续积累的重要性，故 B 正确。A 过度推断；C“必然越安全”绝对化；D 否定了实验室研究，属于绝对化错误。", "tip": "主旨题抓“这提示我们”后的观点句；含“必然/完全/没有意义”的选项多为绝对化陷阱。", "key": "主旨句＝技术成熟靠真实场景持续积累。"}, {"no": 9, "mod": "判断推理", "from": "本周热点（绿色消费）", "type": "single", "stem": "“绿色消费”指以适度节制、保护生态为特征，有益于健康和环境的消费行为。根据该定义，下列属于绿色消费的是（　）", "options": ["小李为凑满减反复下单又退货", "小张自带购物袋、优先选购节能家电", "小王一次买十件同款衣服换着穿", "小赵为撑面子订购最贵的豪华礼盒"], "answer": ["B"], "explain": "B 中“自带购物袋、选节能家电”符合“适度节制、保护生态”，故属于绿色消费。A、C 均属过度与浪费，D 属炫耀性消费，都与“节制、环保”相悖。", "tip": "定义判断抓“关键要件”：本题要件是“适度节制＋保护生态”，逐一比对选项即可。", "key": "绿色消费＝适度节制＋环保健康。"}, {"no": 10, "mod": "判断推理", "from": "第 12 期 · 习思想（逻辑推理）", "type": "single", "stem": "“只有加强党的领导，才能实现民族复兴。”由此可以推出（　）", "options": ["实现了民族复兴，就一定加强了党的领导", "加强了党的领导，就一定实现了民族复兴", "不加强党的领导，也可能实现民族复兴", "加强党的领导与民族复兴无关"], "answer": ["A"], "explain": "“只有 P 才 Q”表示 P 是 Q 的必要条件，即 Q→P（有 Q 必有 P），故 A 正确。B 把必要条件当成了充分条件（P 不一定推出 Q）；C 否定了必要条件；D 与该判断矛盾。", "tip": "“只有……才……”是必要条件：肯后必肯前（Q→P），肯前未必肯后，否前必否后。", "key": "“只有 P 才 Q”：Q→P，P 推不出 Q。"}, {"no": 11, "mod": "数量关系", "from": "速算训练点（百分数加减）", "type": "single", "stem": "某商品原价 200 元，先涨价 10%，再打八折出售，最终售价为（　）", "options": ["176 元", "180 元", "184 元", "190 元"], "answer": ["A"], "explain": "先涨价 10% 得 200×1.1＝220，再打八折得 220×0.8＝176 元，故选 A。", "tip": "连续百分变化用“连乘”：1.1×0.8＝0.88，即最终为原价的 88%；一涨一降并不抵消。", "key": "200×1.1×0.8＝176 元。"}, {"no": 12, "mod": "资料分析", "from": "速算训练点（增长率求基期）", "type": "single", "stem": "2024 年该省粮食总产量约为（　）", "data": "【材料】2025 年某省粮食总产量 380 亿斤，比上年增长 4%。", "options": ["355 亿斤", "365 亿斤", "370 亿斤", "375 亿斤"], "answer": ["B"], "explain": "求基期用除法：380÷(1+4%)＝380÷1.04≈365.4 亿斤，故选 B。", "tip": "“增长 4%”表示现期是基期的 1.04 倍；求基期用÷，别用 380×0.96（那是错的）。", "key": "基期＝现期÷(1+r)＝380÷1.04≈365 亿斤。"}, {"no": 13, "mod": "资料分析", "from": "速算训练点（比重求整体）", "type": "single", "stem": "2025 年该市 GDP 约为（　）", "data": "【材料】2025 年某市第三产业增加值 920 亿元，占全市 GDP 的 46%。", "options": ["1800 亿元", "2000 亿元", "2200 亿元", "2400 亿元"], "answer": ["B"], "explain": "部分÷比重＝整体：920÷46%＝920÷0.46＝2000 亿元，故选 B。", "tip": "已知“部分”和“占比”求“整体”用除法（部分÷比重）；46%≈0.46，可先用 920÷0.46 估算。", "key": "整体＝部分÷比重＝920÷0.46＝2000 亿元。"}], "sl": [{"no": 1, "mod": "归纳概括", "from": "本周新闻 · 科技自立自强", "stem": "材料一：截至 10 月 2 日，华为乾崑累计辅助驾驶里程突破 160 亿公里，真实路况数据成为算法迭代的重要基础。\n材料二：昇腾千卡超节点等国产算力设施加快布局，为人工智能产业提供底层支撑。\n材料三：C919 投入商业运营、中国空间站长期驻留，标志我国在关键领域由跟跑向并跑、领跑迈进。\n材料四：专家指出，核心技术既需实验室里的“从 0 到 1”，也需在广阔应用场景中完成“从 1 到 N”。", "req": "根据给定材料，概括我国科技自立自强的主要表现。", "limit": "不超过 200 字", "points": [{"pt": "智能驾驶等应用技术数据规模快速积累，算法迭代能力增强", "n": 3}, {"pt": "国产算力等基础设施加快布局，夯实人工智能产业底座", "n": 3}, {"pt": "航空航天等关键领域取得突破，实现由跟跑到并跑、领跑", "n": 2}, {"pt": "坚持基础研究与场景应用双轮驱动，形成“从 0 到 1”“从 1 到 N”的闭环", "n": 2}], "sample": "一是应用技术快速迭代：智能驾驶累计里程突破 160 亿公里，真实数据支撑算法进步（3 分）。二是产业底座不断夯实：昇腾等国产算力设施加快布局，支撑人工智能发展（3 分）。三是关键领域实现突破：大飞机商业运营、空间站长期驻留，标志由跟跑向并跑、领跑迈进（2 分）。四是路径清晰：坚持基础研究与场景应用双轮驱动，完成“从 0 到 1”“从 1 到 N”（2 分）。", "tip": "归纳概括先“分层”——按“技术/基础设施/关键领域/路径”归类，再逐条用“动词＋对象＋效果”压缩，注意不超字数、不遗漏分值点。"}, {"no": 2, "mod": "大作文", "from": "本周新闻 · 文化自信 + 大国外交 + 生态文明", "stem": "材料一：贵州晴隆“二十四道拐”抗战公路为保护文物原貌新建替代通行线路，引发“保护与开放”之争。\n材料二：中东局势牵动全球油价，英国柴油价格创近年新高，能源安全与和平发展成为焦点。\n材料三：多地在保护中利用文化遗产、在利用中保护，让历史可感可亲。\n请结合以上材料，联系实际，自选角度，写一篇文章。", "req": "以“在开放与保护之间”为题，结合给定材料与现实，写一篇议论文。", "limit": "1000 字左右", "points": [{"pt": "立意紧扣“保护与开放”的辩证统一，做到扣题、有中心论点（总分论点清晰）", "n": 10}, {"pt": "论证充分：能结合文化遗产保护、能源安全、科技创新等实例展开", "n": 10}, {"pt": "思路清晰、结构完整，分论点之间有逻辑递进", "n": 8}, {"pt": "语言准确流畅，恰当运用金句、引用，结尾有升华", "n": 7}, {"pt": "卷面整洁、字数达标（约 1000 字）", "n": 5}], "sample": "《在开放与保护之间》\n【开头示范】从抗战公路的“保护之争”，到能源命脉的“安全之忧”，再到文化地标的“活化之问”，时代反复追问同一个命题——如何在开放与保护之间找到平衡。保护不是封闭，开放亦非放纵，唯有二者相济，方能行稳致远。\n【分论点一】保护是前提：守护好文化的根脉与发展的底线，才有开放的底气。（可举抗战公路文物本体保护、长江十年禁渔为例）\n【分论点二】开放是路径：让资源可亲可及、让发展彼此成就，保护才有意义。（可举文化遗产数字化展陈、共建“一带一路”为例）\n【分论点三】平衡是智慧：以制度划边界、以创新拓空间，在动态平衡中实现可持续。（可举能源安全与绿色转型双轮驱动为例）\n【结尾示范】“取之有度，用之有节”，则文脉可续、环境可安、发展可久。在开放与保护之间，我们要的不是二选一，而是让保护为开放立根、让开放为保护赋能，共同托举一个更有韧性的未来。", "tip": "大作文先“定立意、列提纲”再落笔：标题即观点；“是什么→为什么→怎么办”或“三个分论点并列/递进”；每个分论点用“观点＋例子＋分析”闭环；结尾回扣标题并适度升华。"}]}, {"id": 3, "date": "2026-10-10", "range": "10/5 – 10/10", "title": "第 3 期周末测试 · 本周串考", "sub": "覆盖本周 019—027 期考公 + 本周成语 + 速算技巧 + 新闻素材", "note": "行测 12 题交卷自动判分；申论 2 题交卷后对照踩分点自评。做题过程中不给答案、不给解析。", "xz": [{"no": 1, "mod": "常识判断", "from": "第 24 期 · 马原（量变质变）", "type": "single", "stem": "“千里之堤，溃于蚁穴”最能体现的哲学道理是（　）", "options": ["矛盾的普遍性与特殊性相互联结", "量的积累达到一定程度必然引起质变", "事物的性质主要由主要矛盾决定", "认识具有反复性和无限性"], "answer": ["B"], "explain": "“蚁穴”是细小的量的积累，最终导致“溃堤”这一质变，体现量变到一定程度必然引起质变，故 B 正确。A、C、D 分别讲矛盾、主要矛盾、认识过程，与“由小到大、由量到质”不符。", "tip": "看到“积少成多、由小到大、千里之堤”一类词语，直接锁定“量变质变规律”。", "key": "量的积累引起质变。"}, {"no": 2, "mod": "常识判断", "from": "第 22 期 · 党史（遵义会议）", "type": "single", "stem": "被称为中国共产党历史上“生死攸关的转折点”的会议是（　）", "options": ["中共一大", "八七会议", "遵义会议", "十一届三中全会"], "answer": ["C"], "explain": "1935 年遵义会议开始确立以毛泽东为代表的马克思主义正确路线在党中央的领导地位，在极端危急关头挽救了党、挽救了红军、挽救了中国革命，是党的历史上生死攸关的转折点，故 C 正确。", "tip": "记“三次转折”式说法：八七会议（由大革命失败到土地革命兴起）、遵义会议（生死攸关的转折点）、十一届三中全会（伟大转折）。", "key": "遵义会议＝生死攸关的转折点（1935）。"}, {"no": 3, "mod": "常识判断", "from": "第 23 期 · 法律（全国人大职权）", "type": "single", "stem": "根据我国宪法，有权制定和修改刑事、民事、国家机构的和其他的基本法律的机关是（　）", "options": ["国务院", "全国人民代表大会", "全国人大常委会", "最高人民法院"], "answer": ["B"], "explain": "全国人民代表大会行使国家立法权，制定和修改刑事、民事、国家机构的和其他的基本法律，故 B 正确。全国人大常委会制定和修改除应由全国人大制定的法律以外的其他法律；国务院制定行政法规。", "tip": "区分“基本法律”（全国人大）与“其他法律”（全国人大常委会）；行政法规由国务院制定。", "key": "基本法律→全国人大。"}, {"no": 4, "mod": "常识判断", "from": "第 27 期 · 科技生活（惯性）", "type": "single", "stem": "关于惯性，下列说法正确的是（　）", "options": ["只有静止的物体才有惯性", "物体速度越大，惯性越大", "惯性大小只由物体的质量决定", "物体受到外力后惯性立即消失"], "answer": ["C"], "explain": "惯性是一切物体的固有属性，任何状态下都有，A 错；惯性大小只与质量有关，与速度无关，B 错、C 对；外力改变运动状态但不能消灭惯性，D 错。", "tip": "惯性大小只看质量；“速度越大惯性越大”是高频干扰项。", "key": "惯性由质量决定。"}, {"no": 5, "mod": "常识判断", "from": "第 27 期 · 地理国情（铁路枢纽）", "type": "single", "stem": "下列铁路枢纽中，位于陇海线与京广线交会处的是（　）", "options": ["徐州", "郑州", "株洲", "兰州"], "answer": ["B"], "explain": "郑州是陇海线与京广线的交会处，故 B 正确。徐州为京沪线与陇海线交会；株洲为京广线与沪昆线交会；兰州为陇海线、兰新线与包兰线交会。", "tip": "记“郑州＝京广＋陇海”，是本题唯一正解。", "key": "郑州：京广×陇海。"}, {"no": 6, "mod": "言语理解与表达", "from": "本周成语（第 26 期）", "type": "single", "stem": "下列句子中，成语使用恰当的一项是（　）", "options": ["这家企业诚信经营，多年来声名狼藉，广受好评。", "他做事一向言不由衷，说出了心里话，大家都很感动。", "面对记者提问，他模棱两可地给出了明确答复。", "合同签了又反悔，这种出尔反尔的做法让人不敢再与他合作。"], "answer": ["D"], "explain": "D 恰当：出尔反尔指说话做事前后矛盾、反复无常，与“签了又反悔”吻合。A 误用：声名狼藉是贬义，与“诚信经营、广受好评”矛盾。B 误用：言不由衷指心口不一，与“说出心里话”矛盾。C 误用：模棱两可指含糊，与“明确答复”自相矛盾。", "tip": "成语题先判褒贬与前后是否矛盾：褒词贬用、贬词褒用、自相矛盾是三大高频陷阱。", "key": "出尔反尔＝反复无常（贬义）。"}, {"no": 7, "mod": "言语理解与表达", "from": "本周新闻（新质生产力）", "type": "single", "stem": "发展新质生产力，不能一哄而上、搞一种模式。各地资源禀赋、产业基础各不相同，必须立足实际、因地制宜，有所选择、有所侧重。\n这段文字意在强调（　）", "options": ["新质生产力只能在一个地区发展", "发展新质生产力必须立足实际、因地制宜", "新质生产力就是发展新兴产业", "各地应完全照搬先进地区的发展经验"], "answer": ["B"], "explain": "文段先否定“一哄而上、搞一种模式”，再用“必须”点明观点——立足实际、因地制宜，故 B 正确。A、D 绝对化或违背文意；C 是偷换概念，发展新质生产力不等于只发展新兴产业。", "tip": "主旨题抓“必须/应当”后的观点句；出现“只能、完全、都”的选项多为绝对化陷阱。", "key": "主旨＝因地制宜发展新质生产力。"}, {"no": 8, "mod": "判断推理", "from": "本周新闻（绿色金融）", "type": "single", "stem": "绿色金融是指为支持环境改善、应对气候变化和资源节约高效利用而提供的金融服务。根据上述定义，下列属于绿色金融的是（　）", "options": ["银行为高污染企业扩大产能提供贷款", "银行为光伏电站项目发行专项绿色债券融资", "银行为房地产开发企业提供普通开发贷款", "公司为员工发放年终奖金"], "answer": ["B"], "explain": "绿色金融的关键要件是“服务对象为环境改善、应对气候变化或资源节约利用”。B 中光伏电站属于清洁能源，符合定义。A 服务于高污染扩产，与“环境改善”相悖；C 是普通开发贷款，与节能环保无关；D 与金融服务无关。", "tip": "定义判断抓关键要件（本题是“用途是否为环保/节能”），逐项比对，缺一即排除。", "key": "绿色金融＝服务环保与节能的金融活动。"}, {"no": 9, "mod": "判断推理", "from": "第 23 期 · 习思想（逻辑推理）", "type": "single", "stem": "“如果加强训练，就能提高成绩。”已知小李没有提高成绩，由此可以推出（　）", "options": ["小李加强了训练", "小李没有加强训练", "所有加强训练的人都提高了成绩", "所有没加强训练的人都提高了成绩"], "answer": ["B"], "explain": "“如果加强训练，就能提高成绩”即“加强训练→提高成绩”，其逆否命题为“没提高成绩→没加强训练”，故 B 正确。A 与该结论矛盾；C 是原命题的重复表达而非必然推出；D 明显错误。", "tip": "“如果 A 则 B”只能推出逆否“非 B→非 A”；肯后、否前都推不出必然结论。", "key": "逆否命题：没提高→没加强训练。"}, {"no": 10, "mod": "数量关系", "from": "速算训练点（利润与百分数）", "type": "single", "stem": "某商品成本 80 元，按 50% 的利润定价，后打八折销售，则每件商品的利润为（　）", "options": ["12 元", "16 元", "20 元", "24 元"], "answer": ["B"], "explain": "按 50% 的利润定价：标价＝80×(1＋50%)＝120（元）。打八折后售价＝120×0.8＝96（元）。利润＝96−80＝16（元），故选 B。", "tip": "“加价 50% 再打八折”净效果＝1.5×0.8＝1.2，即盈利 20%：80×20%＝16 元，可秒算。", "key": "80×1.5×0.8−80＝16 元。"}, {"no": 11, "mod": "资料分析", "from": "速算训练点（增长率求基期）", "type": "single", "stem": "2024 年该省高新技术企业数量约为（　）", "data": "【材料】2025 年某省高新技术企业数量 12,480 家，比上年增长 25%。", "options": ["8,980 家", "9,980 家", "10,480 家", "11,230 家"], "answer": ["B"], "explain": "基期量＝现期量÷(1＋增长率)＝12480÷1.25＝9984，约 9,980 家，故选 B。", "tip": "1.25＝5/4，12480÷1.25＝12480×4÷5＝9984，用特征分数比直接除更快。", "key": "基期＝12480÷1.25≈9,980。"}, {"no": 12, "mod": "资料分析", "from": "速算训练点（比重直除）", "type": "single", "stem": "2025 年该市出口额占进出口总额的比重约为（　）", "data": "【材料】2025 年某市进出口总额 6,240 亿美元，其中出口 3,868 亿美元。", "options": ["52%", "57%", "62%", "67%"], "answer": ["C"], "explain": "比重＝部分÷整体＝3868÷6240。先估 6240×0.62≈3869，与 3868 几乎相等，故比重约为 62%，选 C。", "tip": "比重题用“整百分数试乘”逼近：0.62×6240＝3868.8，一步锁定。", "key": "3868÷6240≈62%。"}], "sl": [{"no": 1, "mod": "归纳概括", "from": "本周新闻 · 新质生产力", "stem": "材料一：《关于发展新质生产力的意见》强调以科技创新推动产业创新，统筹推进传统产业升级、新兴产业壮大与未来产业培育。\n材料二：国家发展改革委指出，发展新质生产力要把握规律、因地制宜，防止一哄而上、搞一种模式。\n材料三：某地立足本地资源发展特色产业，把传统农业与数字技术结合起来，带动农民增收。\n材料四：专家认为，新质生产力不是忽视、放弃传统产业，而是用新技术改造提升传统产业。", "req": "根据给定材料，概括发展新质生产力的主要要求。", "limit": "不超过 200 字", "points": [{"pt": "以科技创新推动产业创新，统筹推进传统产业升级、新兴产业壮大与未来产业培育", "n": 3}, {"pt": "把握规律、因地制宜，立足本地实际，防止一哄而上、搞一种模式", "n": 3}, {"pt": "立足资源禀赋发展特色产业，推动数字技术与实体经济深度融合", "n": 2}, {"pt": "不忽视、不放弃传统产业，用新技术改造提升传统产业", "n": 2}], "sample": "一是坚持创新引领：以科技创新推动产业创新，统筹推进传统产业升级、新兴产业壮大与未来产业培育（3 分）。二是坚持因地制宜：把握规律、立足本地实际，防止一哄而上、搞一种模式（3 分）。三是立足禀赋发展特色产业：把传统农业与数字技术结合，推动数字技术与实体经济融合，带动农民增收（2 分）。四是统筹新旧产业：不忽视、不放弃传统产业，用新技术改造提升传统产业（2 分）。", "tip": "归纳概括先“分层”：按“创新引领／因地制宜／特色产业／新旧统筹”归类，再逐条用“动词＋对象＋效果”压缩，不超字数、不漏分值点。"}, {"no": 2, "mod": "大作文", "from": "本周新闻 · 新质生产力 + 县域旅游 + 地方发展", "stem": "材料一：《关于发展新质生产力的意见》强调因地制宜，反对一哄而上、搞一种模式。\n材料二：国庆期间县域旅游走热，一批小城靠特色文化与风物吸引游客，迎来“泼天流量”。\n材料三：某地照搬外地模式建设产业园区，因脱离自身实际而长期闲置。\n请结合以上材料，联系实际，自选角度，写一篇文章。", "req": "以“因地制宜方能行稳致远”为题，结合给定材料与现实，写一篇议论文。", "limit": "1000 字左右", "points": [{"pt": "立意紧扣“因地制宜”，做到扣题、有中心论点（总分论点清晰）", "n": 10}, {"pt": "论证充分：能结合县域旅游、产业培育、乡村振兴等实例展开", "n": 10}, {"pt": "思路清晰、结构完整，分论点之间有逻辑递进", "n": 8}, {"pt": "语言准确流畅，恰当运用金句、引用，结尾有升华", "n": 7}, {"pt": "卷面整洁、字数达标（约 1000 字）", "n": 5}], "sample": "《因地制宜方能行稳致远》\n【开头示范】同样的“新质生产力”，在沿海城市是算力与芯片，在西部小城可能是特色农业与文旅；同样一场“泼天流量”，接得住的县城留住客人，接不住的只落得一地鸡毛。可见，脱离实际的一哄而上，热闹一时而难以为继；唯有因地制宜，方能行稳致远。\n【分论点一】因地制宜，前提是认清“我是谁”。（可举某地照搬外地产业园区却长期闲置为反面案例，说明脱离禀赋的“复制粘贴”必然水土不服）\n【分论点二】因地制宜，关键是找准“我能做什么”。（可举县域旅游靠特色文化与风物出圈，把“土”资源变成“热”产业）\n【分论点三】因地制宜，落点是把握好“进与稳”的平衡。（可举新质生产力以科技创新推动产业创新，同时不放弃、善用传统产业）\n【结尾示范】橘生淮南则为橘，生于淮北则为枳。发展之道不在照抄作业，而在量身裁衣——立足一方水土，走出自己的路，发展的根基才会越扎越深，前行的步伐才能行稳致远。", "tip": "大作文先“定立意、列提纲”：标题即观点；分论点用“是什么／为什么／怎么办”或并列递进；每个分论点用“观点＋例子＋分析”闭环；结尾回扣标题并适度升华。"}]}, {"id": 4, "date": "2026-10-17", "range": "10/12 – 10/17", "title": "第 4 期周末测试 · 本周串考", "sub": "覆盖 10/12—10/17 本周考公（含第 41—42 期）+ 本周成语速记 + 本周新闻素材", "note": "行测 12 题交卷自动判分；申论 2 题交卷后对照踩分点自评。做题过程中不给答案、不给解析。", "xz": [{"no": 1, "mod": "常识判断", "from": "第 41 期 · 科技生活（光的反射）", "type": "single", "stem": "下列现象中，由光的反射形成的是（　）", "options": ["池水看起来比实际浅", "用平面镜看到自己的面容", "用放大镜把字看得更大", "雨后天空出现彩虹"], "answer": ["B"], "explain": "用平面镜看到面容，是光在镜面发生反射，B 正确。池水变浅（A）是折射，放大镜（C）是凸透镜折射，彩虹（D）是折射与色散，均属折射现象。", "tip": "记口诀：成“像”看倒影＝反射，发生“变浅、放大、折断”＝折射。", "key": "平面镜成像／倒影＝反射。"}, {"no": 2, "mod": "常识判断", "from": "第 42 期 · 文史（选官制度）", "type": "single", "stem": "我国古代选官制度按出现时间先后排列，正确的是（　）", "options": ["世卿世禄—九品中正制—察举制—科举制", "世卿世禄—察举制—九品中正制—科举制", "察举制—世卿世禄—科举制—九品中正制", "科举制—察举制—九品中正制—世卿世禄"], "answer": ["B"], "explain": "正确顺序为：先秦世卿世禄—汉代察举制—魏晋南北朝九品中正制—隋唐科举制，故 B 正确。A、C、D 均颠倒了时间先后。", "tip": "记时间轴：世卿世禄（先秦）→察举（汉）→九品中正（魏晋）→科举（隋唐）。", "key": "世卿世禄→察举→九品中正→科举。"}, {"no": 3, "mod": "常识判断", "from": "第 41 期 · 地理（黄河概况）", "type": "single", "stem": "关于黄河，下列说法正确的是（　）", "options": ["黄河发源于青藏高原的唐古拉山", "黄河中游流经黄土高原，是世界上含沙量最大的河流", "黄河下游河床低于两岸地面，形成“地上河”", "黄河只流经我国地势的第三级阶梯"], "answer": ["B"], "explain": "黄河中游穿越黄土高原，水土流失严重，含沙量居世界首位，B 正确。A 错，黄河发源于巴颜喀拉山（唐古拉山是长江源头）；C 错，“地上河”指河床高于两岸地面；D 错，黄河自西向东跨三级阶梯。", "tip": "源头别混：黄河＝巴颜喀拉山，长江＝唐古拉山。", "key": "黄河中游送沙，含沙量世界第一。"}, {"no": 4, "mod": "常识判断", "from": "第 42 期 · 法律（离婚冷静期）", "type": "single", "stem": "根据民法典，夫妻协议离婚的离婚冷静期为（　）", "options": ["15 日", "30 日", "60 日", "90 日"], "answer": ["B"], "explain": "协议离婚的冷静期为自婚姻登记机关收到申请之日起 30 日，B 正确。期满后 30 日内双方须亲自申领离婚证，未申领的视为撤回申请；诉讼离婚无冷静期。", "tip": "区分两个 30 日：冷静期 30 日、发证期 30 日。", "key": "协议离婚冷静期＝30 日。"}, {"no": 5, "mod": "常识判断", "from": "第 41 期 · 马原（实践与认识）", "type": "single", "stem": "“实践是检验真理的唯一标准”这句话表明（　）", "options": ["认识来源于书本知识", "真理要靠实践的检验来证明", "实践可以脱离认识单独存在", "认识与实践相互独立、互不影响"], "answer": ["B"], "explain": "实践是检验认识真理性的唯一标准，一种认识是否正确，只能由实践来检验，B 正确。认识的来源是实践而非书本（A 错）；认识与实践相互联系、相互影响（C、D 错）。", "tip": "抓住“唯一标准”四字，对应实践对认识的检验作用。", "key": "实践是检验真理的唯一标准。"}, {"no": 6, "mod": "言语理解与表达", "from": "第 41 期 · 成语（重蹈覆辙）", "type": "single", "stem": "填入下列句子横线处最恰当的一项是（　）\n若不认真总结这次失败的教训，类似的问题还会＿＿＿＿。", "options": ["重整旗鼓", "重蹈覆辙", "前车之鉴", "故地重游"], "answer": ["B"], "explain": "句意为“不吸取教训会重犯错误”，“重蹈覆辙”符合，B 正确。“重整旗鼓”为褒义（失败后再干）、“前车之鉴”是名词性短语、“故地重游”指重游旧地，均不合语境。", "tip": "看到“不吸取教训＋再犯错误”，直接锁定“重蹈覆辙”。", "key": "不吸取教训再犯错＝重蹈覆辙。"}, {"no": 7, "mod": "言语理解与表达", "from": "本周新闻 · 折叠屏与供应链", "type": "single", "stem": "折叠屏手机看似只是屏幕形态的变化，实则牵动铰链、柔性屏、精密制造等一整条供应链。谁能率先把良率做上去、把成本降下来，谁就能在下一代终端的竞争中占据主动。\n这段文字意在说明（　）", "options": ["折叠屏手机的价格偏高", "铰链是折叠屏唯一的技术难点", "折叠屏的竞争本质是供应链与制造能力之争", "消费者应当理性看待尝鲜溢价"], "answer": ["C"], "explain": "文段先指出折叠屏牵动整条供应链，再强调“谁能把良率做上去、成本降下来”就能占据主动，落点在供应链与制造能力的竞争，C 正确。A、D 是消费侧话题，B“唯一”过于绝对。", "tip": "主旨题抓“实则／更”等转折与递进后的落脚句。", "key": "折叠屏竞争＝供应链与制造能力之争。"}, {"no": 8, "mod": "判断推理", "from": "第 14 批 · 定义判断（沉没成本）", "type": "single", "stem": "沉没成本是指已经发生且无法收回的支出，理性决策不应受其影响。根据该定义，下列体现“沉没成本谬误”的是（　）", "options": ["小张买了电影票，看了半小时发现是烂片，仍忍着看完", "小李放弃已过期的健身卡，重新办了一张", "小王把用不上的旧手机送给朋友", "小赵退掉了不合适的课程并获得部分退款"], "answer": ["A"], "explain": "电影票款已花且不可收回（沉没成本），小张却因“已经花了钱”继续看烂片，属沉没成本谬误，A 正确。B、C、D 都及时处置、止损，未受沉没成本左右。", "tip": "定义判断抓链条：“已发生、不可收回”＋“仍据此做决策”。", "key": "沉没成本谬误＝为已花的钱继续将就。"}, {"no": 9, "mod": "判断推理", "from": "第 14 批 · 逻辑判断（逆否命题）", "type": "single", "stem": "某班学生中，所有喜欢篮球的同学都喜欢跑步；小明不喜欢跑步。由此可以推出（　）", "options": ["小明喜欢篮球", "小明不喜欢篮球", "有些喜欢跑步的同学不喜欢篮球", "喜欢跑步的同学都喜欢篮球"], "answer": ["B"], "explain": "由“喜欢篮球→喜欢跑步”，其逆否命题为“不喜欢跑步→不喜欢篮球”，题干又给出“小明不喜欢跑步”，故可推出“小明不喜欢篮球”，B 正确。A 与题干矛盾，C、D 无法推出。", "tip": "“所有 A 是 B”等价于“非 B 是非 A”，但不能反推“所有 B 是 A”。", "key": "充分条件用逆否，切忌倒推。"}, {"no": 10, "mod": "数量关系", "from": "第 14 批 · 工程问题", "type": "single", "stem": "一项工程，甲单独做需 12 天，乙单独做需 24 天。两人合作，需几天完成（　）", "options": ["6", "8", "9", "10"], "answer": ["B"], "explain": "赋值工作总量为 24（12 与 24 的最小公倍数），甲效率为 2、乙效率为 1，合作效率为 3，24÷3＝8 天，B 正确。", "tip": "赋值法取两时间的最小公倍数，效率好算且不出现分数。", "key": "合作时间＝总量÷效率之和。"}, {"no": 11, "mod": "资料分析", "from": "第 15 批 · 比重计算", "type": "single", "stem": "某市 2025 年新能源汽车产量为 40 万辆，同比增长 25%；当年汽车总产量为 200 万辆。2025 年新能源汽车产量占汽车总产量的比重为（　）", "options": ["15%", "18%", "20%", "25%"], "answer": ["C"], "explain": "比重＝部分÷总体＝40÷200＝20%，C 正确。同比增长 25% 是干扰信息，计算比重时用不到。", "tip": "比重题先看清“部分÷总体”，未被问及的增长率不要代入。", "key": "比重＝部分÷总体。"}, {"no": 12, "mod": "资料分析", "from": "第 15 批 · 增长率计算", "type": "single", "stem": "接上题，若 2024 年该市汽车总产量为 180 万辆，则 2025 年汽车总产量比 2024 年增长（　）", "options": ["约 8.9%", "约 10.0%", "约 11.1%", "约 12.5%"], "answer": ["C"], "explain": "增长率＝（现期−基期）÷基期＝（200−180）÷180≈11.1%，C 正确。", "tip": "增长率的分母是“基期量”（180），别写成现期量。", "key": "增长率＝(现期−基期)÷基期。"}], "sl": [{"no": 1, "mod": "归纳概括", "from": "本周新闻 · 校园食品安全", "stem": "材料一：天水幼儿园铅中毒案一审宣判，园方负责人被判处无期徒刑；调查指出校园餐食采购、加工与检测等环节存在监管漏洞。\n材料二：多地推行“明厨亮灶”，把后厨加工过程实时公示；部分学校建立“校长陪餐制”，校领导与学生同桌就餐。\n材料三：有关部门要求健全校园食品全链条追溯体系，做到原料来源可查、去向可追、责任可究。\n材料四：专家建议拓宽社会监督渠道，公开食堂招标与检测信息，让家长、媒体共同参与。", "req": "根据给定材料，概括守护校园食品安全的主要举措。", "limit": "不超过 200 字", "points": [{"pt": "推行“明厨亮灶”，把后厨加工过程实时公示，实现可视化监督", "n": 3}, {"pt": "建立校长（园领导）陪餐制，让管理者与学生同桌就餐、日常把关", "n": 3}, {"pt": "健全全链条追溯体系，做到来源可查、去向可追、责任可究", "n": 2}, {"pt": "拓宽社会监督渠道，公开招标与检测信息，引导家长、媒体共同参与", "n": 2}], "sample": "一是推行“明厨亮灶”：把后厨加工过程实时公示，实现可视化监督（3 分）。二是建立陪餐制度：由校（园）领导与学生同桌就餐，日常把关（3 分）。三是健全追溯体系：做到原料来源可查、去向可追、责任可究（2 分）。四是拓宽社会监督：公开食堂招标与检测信息，引导家长、媒体共同参与（2 分）。", "tip": "归纳概括先“分层”（监管方式／责任落实／追溯机制／社会共治），再用“动词＋对象＋效果”压缩，不超字数、不漏分值点。"}, {"no": 2, "mod": "提出对策", "from": "本周新闻 · 扩内需与消费", "stem": "材料一：有观点认为，提振消费只要“发钱”就行，但发完钱后消费很快回落。\n材料二：数据显示，居民储蓄意愿仍偏高，部分家庭因养老、医疗、教育等支出预期而不敢消费。\n材料三：某地通过“以旧换新”补贴家电、汽车，带动大宗消费；又发展县域商业、夜间经济，让消费场景更丰富。\n材料四：专家指出，稳就业、稳收入是消费的根本，只有收入预期稳定，消费才能持续。", "req": "请结合给定材料，就“如何让居民敢消费、愿消费”，提出对策建议。", "limit": "不超过 300 字", "points": [{"pt": "稳定就业与收入，夯实消费根基：稳岗扩就业、提高中低收入群体收入", "n": 3}, {"pt": "完善社会保障，改善支出预期：补强养老、医疗、教育、托育等保障，减少后顾之忧", "n": 3}, {"pt": "用好消费政策工具：以旧换新等补贴撬动家电、汽车等大宗消费", "n": 2}, {"pt": "丰富消费场景与供给：发展县域商业、夜间经济、文旅消费，优化消费环境", "n": 2}], "sample": "一、稳就业稳收入，夯实根基。把稳岗扩就业放在优先位置，提高中低收入群体收入，稳定居民收入预期（3 分）。二、补强社会保障，改善预期。完善养老、医疗、教育、托育等制度，降低家庭后顾之忧，让居民“敢花”（3 分）。三、用好政策工具。以“以旧换新”等补贴撬动家电、汽车等大宗消费（2 分）。四、丰富场景供给。发展县域商业、夜间经济与文旅消费，优化消费环境，让居民“愿花”（2 分）。", "tip": "对策题按“根本—保障—政策—场景”分层，每条用“总括句＋具体做法”的写法，既得分又清晰。"}]}, {"id": 5, "date": "2026-10-24", "range": "2026/10/19 – 2026/10/24", "title": "第 5 期周末测试 · 本周串考", "sub": "覆盖 2026/10/19 – 2026/10/24 本周考公（含本期常识/行测/词语速记）", "note": "行测 12 题交卷自动判分；申论 2 题交卷后对照踩分点自评。做题过程中不给答案、不给解析。", "xz": [{"date": "2026-10-19", "src": "issue", "no": 1, "mod": "常识判断", "type": "single", "stem": "我国财政预算“四本账”包括一般公共预算、政府性基金预算、国有资本经营预算和社会保险基金预算。关于“四本账”，下列表述错误的是：", "options": ["一般公共预算即安排用于保障和改善民生等方面的收支预算", "政府性基金预算包含铁路建设基金、土地出让收入、专项债等", "国有资本经营预算应当按照收支平衡的原则编制，不列赤字", "社会保险基金预算可以调出资金到其他预算中"], "answer": ["D"], "explain": "逐项判断：A正确，一般公共预算就是安排用于保障和改善民生、推动经济社会发展、维护国家安全、维持国家机构正常运转等方面的收支预算；B正确，政府性基金预算包含铁路建设基金、民航发展基金、土地出让收入和专项债等；C正确，国有资本经营预算应当按照收支平衡的原则编制，以收定支，不列赤字；D错误，社会保险基金预算专款专用，专项用于社会保险，只进不出，不能调出资金到其他预算中。本题为选非题，故正确答案为D。", "tip": "①“四本账”分工必背：一般公共预算管民生运转、政府性基金管特定公共事业（土地出让、专项债）、国有资本经营预算不列赤字、社保基金预算只进不出；②“不列赤字”是国有资本经营预算的标志性规则；③财政类选非题常设“可以调剂/可以调出”类表述，社保基…", "key": "财政四本账：一般公共管民生、政府性基金管专项（土地出让）、国资预算不列赤字、社保", "from": "第 1 期 · 本周常识"}, {"date": "2026-10-24", "src": "xc", "no": 2, "mod": "数量关系", "type": "single", "stem": "某单位有甲和乙2个办公室，分别有职工5人和4人。每周从这9名职工中随机抽取1人下沉社区担任志愿者（同一人有可能被连续、重复选中）。问7月前2周的志愿者均来自甲办公室的概率在以下哪个范围内？", "options": ["不到25%", "25%~35%之间", "35%~45%之间", "超过45%"], "answer": ["B"], "explain": "思路：独立事件概率乘法。详解：每周从9人中抽1人，两周总情况=9×9=81种；两周均来自甲办公室=5×5=25种。所求概率=25/81≈30.9%，落在25%~35%之间。故答案为B。", "tip": "易错点：同一人可重复选中说明是有放回抽样，两周相互独立，不能用C(9,2)组合；甲办公室5人、总9人。", "key": "思路：独立事件概率乘法。详解：每周从9人中抽1人，两周总情况=9×9=81种；两", "from": "第 2 批 · 行测加练"}, {"date": "2026-10-20", "src": "issue", "no": 3, "mod": "常识判断", "type": "single", "stem": "关于个人信息保护，下列说法不符合我国法律规定的是：", "options": ["通过自动化决策方式向个人进行商业营销，应同时提供不针对其个人特征的选项或便捷的拒绝方式", "通过人脸识别技术所收集的个人图像、身份识别信息只能用于维护公共安全目的", "个人信息和隐私有密切的关系，个人信息当中的私密信息适用有关隐私权的规定", "用户量巨大的个人信息处理者需要定期发布个人信息保护社会责任报告"], "answer": ["B"], "explain": "逐项判断：A正确，通过自动化决策方式向个人进行信息推送、商业营销，应同时提供不针对其个人特征的选项或便捷拒绝方式；B错误，公共场所采集的个人图像、身份识别信息原则上只能用于维护公共安全目的，但取得个人单独同意的可用于其他目的，选项说\"只能\"过于绝对；C正确，民法典规定个人信息中的私密信息适用有关隐私权的规定；D正确，提供重要互联网平台服务、用户数量巨大、业务类型复杂的处理者应定期发布个人信息保护社会责任报告。本题选不符合项，故正确答案为B。", "tip": "①\"只能/一律\"类绝对表述要警惕法律中的例外条款；②个保法重点制度：告知同意、敏感信息单独同意、自动化决策拒绝权、大型平台社会责任报告；③私密信息优先适用民法典隐私权规则。", "key": "人脸识别信息“只能用于公共安全”漏了“个人单独同意”的例外条款", "from": "第 3 期 · 本周常识"}, {"date": "2026-10-22", "src": "idiom", "no": 4, "mod": "言语理解与表达", "type": "single", "stem": "为应试而放弃思考，是____。", "options": ["背道而驰", "因小失大", "得不偿失", "本末倒置"], "answer": ["D"], "explain": "把主要的和次要的、本质和非本质的关系弄颠倒了", "tip": "易混：背道而驰、因小失大、得不偿失 需结合语境辨析", "key": "成语填空：本末倒置", "from": "第 4 期 · 词语速记"}, {"date": "2026-10-19", "src": "issue", "no": 5, "mod": "常识判断", "type": "single", "stem": "下图为夏季某天我国两个城市的日月升落时间示意图，下列与之相关的说法正确的是：", "options": ["左图城市比右图城市纬度高", "这一天是农历的二十左右", "左图城市比右图城市位置更靠东", "两地的人所看到的月相是不同的"], "answer": ["A"], "explain": "逐项判断：A项正确，夏季北半球纬度越高昼越长，左图昼长约15小时25分长于右图约14小时07分，故左图城市纬度更高；B项错误，图中月相为残月（下娥眉月），约农历二十七左右而非二十；C项错误，地球自西向东自转，越靠东日出越早，右图日出04:55早于左图06:31，故右图更靠东；D项错误，两地月相同为残月，仅因经度不同导致升降时刻有差异，月相本身相同。故正确答案为A。", "tip": "①夏季昼长越长纬度越高（北半球）；②月相记忆：上弦月初七初八、满月十五、下弦月廿二三、残月廿七前后；③位置靠东则日出越早。", "key": "夏季昼长越长纬度越高；月相定日：初七八上弦、十五满月、廿七八残月。", "from": "第 5 期 · 本周常识"}, {"date": "2026-10-24", "src": "issue", "no": 6, "mod": "常识判断", "type": "single", "stem": "下图是一辆汽车行驶在道路上速度（V）随时间（T）变化的关系图，则下列说法正确的是（ ）。", "options": ["汽车在第6分钟的时候回到原出发点", "汽车在第2分钟的时候距离出发点最远", "汽车在第2分钟的速度与第6分钟的速度大小相等", "汽车在0-2分钟时的加速度与2-4分钟时的加速度相同"], "answer": ["C"], "explain": "逐项判断：A错误，V-T图面积表示位移，第6分钟时面积不为零，未回到出发点；B错误，第4分钟时速度由正变负（过零），此时位移面积最大，离出发点最远；C正确，2-6分钟图像为同一直线（斜率恒定），由对称性可知第2分钟速度大小等于第6分钟速度大小；D错误，0-2分钟斜率为正（加速），2-4分钟斜率为负（减速），加速度方向不同，不相同", "tip": "易错点：误以为速度为零时回到出发点（实则V-T图面积才是位移）；或误以为加速度正负号相同就相同（加速度是矢量）；记忆要点", "key": "真题演练：C", "from": "第 6 期 · 本周常识"}, {"date": "2026-10-19", "src": "idiom", "no": 7, "mod": "言语理解与表达", "type": "single", "stem": "未成年人网络游戏防沉迷机制是否有效，不只取决于平台管控是否严格，也取决于是否存在其他漏洞。对此，为绕开防沉迷机制而设计出来的种种方法，都应予以系统清理和整治。对于落实未成年人保护责任，运营商唯有诚心正意而非____，才能真正完善未成年人网络游戏防沉迷机制。", "options": ["虚张声势", "口是心非", "虚与委蛇", "阳奉阴违"], "answer": ["C"], "explain": "对人虚情假意、敷衍应酬", "tip": "“委蛇”读 wēi yí，不读 wěi shé。指对人虚情假意、敷衍应酬。与“口是心非”比：后者侧重心口不一；与“虚张声势”比：后者侧重假装声势吓人。看到“诚心正意而非…”反义引导选它。", "key": "成语填空：虚与委蛇", "from": "第 7 期 · 词语速记"}, {"date": "2026-10-21", "src": "issue", "no": 8, "mod": "常识判断", "type": "single", "stem": "习近平总书记强调，选人用人要加强党性鉴别，注重考察干部的境界格局和忠诚度廉洁度。下列与党性相关的说法正确的是：", "options": ["树立和践行正确政绩观，起决定性作用的是党性", "强党性，就是要自觉用马克思主义思想改造客观世界", "党性、党风、党纪是有机整体，党性是根本，党风是保障，党纪是表现", "作风问题本质上是党性问题，要把作风建设摆在党性修养的首位"], "answer": ["A"], "explain": "逐项判断：A正确，2022年3月1日春季学期中青班开班式指出树立和践行正确政绩观，起决定性作用的是党性；B错误，'强党性'是自觉用新时代中国特色社会主义思想改造主观世界，不是改造客观世界；C错误，党性、党风、党纪是有机整体，党性是根本，党风是表现，党纪是保障，选项把后两者说反；D错误，作风问题本质上是党性问题，但要把政治修养摆在党性修养的首位，不是作风建设。故正确答案为A。", "tip": "易错点：B把'改造主观世界'误记成'客观世界'、C把'党风是表现、党纪是保障'互换、D把'政治修养摆在首位'误记成'作风建设摆在首位'；记忆要点：树立和践行正确政绩观，起决定性作用的是党性。", "key": "牢记政治理论：A", "from": "第 8 期 · 本周常识"}, {"date": "2026-10-19", "src": "issue", "no": 9, "mod": "常识判断", "type": "single", "stem": "关于我国水电建设，下列说法正确的是：", "options": ["刘家峡水电站是中国第一座自行设计、自制设备和自行施工的大型水力发电站", "小浪底水利枢纽被誉为“万里长江第一坝”，是长江干流上第一座大型水电工程", "白鹤滩水电站全部机组投产发电，标志着我国建成世界最大的清洁能源走廊", "新安江水电站位于甘肃省境内黄河干流，是我国第一座百万千瓦级大型水电站"], "answer": ["C"], "explain": "逐项判断：A错误，中国第一座自行勘测、设计、施工并制造设备的大型水电站是新安江水电站（浙江钱塘江水系）；B错误，被誉为“万里长江第一坝”的是葛洲坝水利枢纽（湖北宜昌），小浪底位于河南黄河干流；C正确，2022年12月20日白鹤滩水电站全部机组投产发电，标志着我国在长江上全面建成世界最大清洁能源走廊；D错误，新安江水电站位于浙江杭州建德，刘家峡水电站才是位于甘肃永靖黄河干流的我国首座百万千瓦级水电站。故正确答案为C。", "tip": "①水电地标对照：新安江（浙江，第一座自建）、刘家峡（甘肃黄河，首座百万千瓦）、葛洲坝（长江第一坝）、白鹤滩（世界第二大水电站、西电东送）、小浪底（河南黄河）；②“第一座”“最”类称号必须与具体电站绑定记忆；③看到“甘肃/黄河”先排除新安江。", "key": "水电“第一”称号绑电站记：新安江自建第一、刘家峡百万千瓦、葛洲坝长江第一坝。", "from": "第 9 期 · 本周常识"}, {"date": "2026-10-22", "src": "xc", "no": 10, "mod": "图形推理", "type": "single", "stem": "接下来的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "三个图上都有＋号，×号，黑圆，白圆但是位置不相同。先来看＋号的位置，图一到图二＋号顺时针走了3个格，图二到图三顺时针＋号走了4个格，所以图四应该是在图三的基础上顺时针走5个格。再来看×号的位置，图一到图二×顺时针走了1个格，图二到图三×顺时针走了1个格，所以图四应该是在图三的基础上顺时针走1个格。看黑圆的位置，图一到图二顺时针走了6个格，图二到图三顺时针走了5个格，所以图四应该是在图三的基础上顺时针走了4个格。看白圆的位置，图一到图二顺时针走了2个格，图二到图三顺时针走了2个格，所以图四应该是在图三的基础上顺时针走2个格。只有选项A符合，所以选A。", "tip": "图形推理：先观察元素组成、数量与位置规律，再验证选项。", "key": "图形推理：对称/数量/位置规律。", "from": "第 10 批 · 行测加练"}, {"date": "2026-10-23", "src": "xc", "no": 11, "mod": "科学推理", "type": "single", "stem": "水平地面上有甲、乙两块由不同材质构成、质地分布均匀的长方体金属块。已知甲的体积>乙的体积，甲的底面积<乙的底面积，甲的质量>乙的质量。则以下判断一定正确的有： ①甲的高度>乙的高度 ②甲的高度<乙的高度 ③甲的密度>乙的密度 ④甲的密度<乙的密度", "options": ["①", "③", "①③", "②④"], "answer": ["A"], "explain": "思路：长方体V=S·h，密度ρ=m/V；详解：高度h=V/S，甲V更大、S更小，则h甲必大于h乙，①正确②错误；密度ρ=m/V，甲m更大但V也更大，两因素方向相反，密度大小无法确定，③④都不一定成立。故答案为A。", "tip": "易错点：把“甲质量大”直接推成“甲密度大”；密度ρ=m/V，质量大且体积也大时无法确定密度大小。", "key": "思路：长方体V=S·h，密度ρ=m/V；详解：高度h=V/S，甲V更大、S更小，", "from": "第 11 批 · 行测加练"}, {"date": "2026-10-19", "src": "xc", "no": 12, "mod": "判断推理", "type": "single", "stem": "某次足球比赛前，甲、乙、丙、丁四位运动员猜测他们的上场情况。 甲：我们四人都不会上场； 乙：我们中有人会上场； 丙：乙和丁至少有一人上场； 丁：我会上场。 四人中有两人猜测为真两人猜测为假，则以下哪项断定成立？", "options": ["猜测为真的是乙和丙", "猜测为真的是甲和丁", "猜测为真的是甲和丙", "猜测为真的是乙和丁"], "answer": ["A"], "explain": "本题属于真假推理题。 第一步：找出题干矛盾命题。 甲：我们四人都不会上场； 乙：我们中有人会上场； 丙：乙或丁； 丁：丁。 甲说“我们四人都不会上场”和乙说“我们中有人会上场”是矛盾关系，则必有一真必有一假。已知四人中有两人猜测为真两人猜测为假，说明丙和丁的猜测也必然是一真一假。 第二步：看其余。 假设丁的猜测为真，则丁会上场，而“丁”为“乙或丁”的其中一项，此时丙的猜测也一定为真，那么丙、丁的猜测均为真，与题干要求的一真一假矛盾，故丁的猜测一定为假，即丁不会上场，则丙的猜测为真，说明乙或丁会上场，既然丁不会上场，那么上场的为乙，也就是说四个人中有人会上场，则乙的猜测为真，甲的猜测为假，即猜测为真的是乙和丙。 ⇒ 正确答案为A。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。", "key": "本题属于真假推理题。 第一步：找出题干矛盾命题。 甲：我们四人都不会上场； 乙：", "from": "第 12 批 · 行测加练"}], "sl": [{"no": 1, "mod": "文章写作", "from": "申论真题 · 国考", "stem": "【真题材料摘要】G市工业大学冯教授团队入驻桃李镇清池村，以「与村民一起动手」代替授课，从建大椅子、家庭美术馆起步，重新挖掘「烧奔塔」「成人礼」等传统习俗，举办乡村时装秀。主张以「膜拜」而非「治理教导」的心态介入乡村，探索「超越艺术」的路径，当好挖掘本土文化特色的「运营官」。；N市隆金公司专注汽车门把手等配件，2012年起每年投入数千万元建设全自动数字化车间，依托企业研究院、海外研发中心、产学研合作吸引创新人才，近三年完成研发项目超300项、专利295项，95%产品实现国产化替代，迈入「单项冠军」方阵。；J省江平县曾面临乡镇卫生院人才奇缺困境，通过稳定现有人才、绩效考核拉开收入差距、急缺人才现场考试招录、购房补贴、偏远乡镇补助、编制周转池、县管乡用乡管村用、实训基地轮训、与三甲医院共建院士工作站和远程会诊中心等举措破解基层医疗人才难题。；S市涌现一批公共文化空间：畅雅艺术空间辐射6200居民、活动火爆；但不少民营美术馆、24小时书院冷冷清清；大型实体书店场景营造同质化、审美疲劳；市美术馆被当「网红打卡点」；同时存在载体规模偏小、布局分散、缺少主题型创意型空间等问题。；某大学图书馆王师傅以桌椅维修为主的木工工作，修抽屉、做木门、为古籍定制木箱、打磨卡窗户的小木块，在修缮中创造、于毫末处耕耘，为师生温暖笃定的生活秩序默默付出，展现平凡岗位的工匠精神。\n「给定资料5」中提到：「投入自己的领域，不断『打磨』、不断『修补』，为人们温暖笃定的生活秩序默默付出，稳步前行。」请根据对这句话的理解，参考给定资料，联系实际，自选角度，自拟题目，写一篇文章。要求：观点明确、见解深刻；参考给定资料但不拘泥于给定资料；思路清晰、语言流畅；字数 1000-1200 字。", "req": "「给定资料5」中提到：「投入自己的领域，不断『打磨』、不断『修补』，为人们温暖笃定的生活秩序默默付出，稳步前行。」请根据对这句话的理解，参考给定资料，联系实际，自选角度，自拟题目，写一篇文章。要求：观点明确、见解深刻；参考给定资料但不拘泥于给定资料；思路清晰、语言流畅；字数 1000-1200 字。", "limit": "不超过300字", "points": [{"pt": "写作思路参考：中心论点——在平凡岗位上以匠心打磨、以行动修补，为生活秩序默默付出，本身就是不凡的价值创造。分论点示例：①匠心在于对品质的坚守——于细微处见真章（", "n": 11}, {"pt": "行动在于对责任的担当——小补丁也有大意义（一扇木门、一个窗卡背后是被重视被关怀的人）", "n": 11}, {"pt": "平凡可以成就非凡——每一个默默付出的人共同支撑社会的温暖秩序。可联系工匠精神、基层治理、为民服务等角度展开。", "n": 11}], "sample": "写作思路参考：中心论点——在平凡岗位上以匠心打磨、以行动修补，为生活秩序默默付出，本身就是不凡的价值创造。分论点示例：①匠心在于对品质的坚守——于细微处见真章（王师傅修椅子、做木箱、打磨小木块）；②行动在于对责任的担当——小补丁也有大意义（一扇木门、一个窗卡背后是被重视被关怀的人）；③平凡可以成就非凡——每一个默默付出的人共同支撑社会的温暖秩序。可联系工匠精神、基层治理、为民服务等角度展开。", "tip": "综合分析题：先分层再压缩，每条“总括句＋具体做法”，不超字数、不漏分值点。"}, {"no": 2, "mod": "贯彻执行", "from": "申论真题 · 国考", "stem": "【真题材料摘要】G市工业大学冯教授团队入驻桃李镇清池村，以「与村民一起动手」代替授课，从建大椅子、家庭美术馆起步，重新挖掘「烧奔塔」「成人礼」等传统习俗，举办乡村时装秀。主张以「膜拜」而非「治理教导」的心态介入乡村，探索「超越艺术」的路径，当好挖掘本土文化特色的「运营官」。；N市隆金公司专注汽车门把手等配件，2012年起每年投入数千万元建设全自动数字化车间，依托企业研究院、海外研发中心、产学研合作吸引创新人才，近三年完成研发项目超300项、专利295项，95%产品实现国产化替代，迈入「单项冠军」方阵。；J省江平县曾面临乡镇卫生院人才奇缺困境，通过稳定现有人才、绩效考核拉开收入差距、急缺人才现场考试招录、购房补贴、偏远乡镇补助、编制周转池、县管乡用乡管村用、实训基地轮训、与三甲医院共建院士工作站和远程会诊中心等举措破解基层医疗人才难题。；S市涌现一批公共文化空间：畅雅艺术空间辐射6200居民、活动火爆；但不少民营美术馆、24小时书院冷冷清清；大型实体书店场景营造同质化、审美疲劳；市美术馆被当「网红打卡点」；同时存在载体规模偏小、布局分散、缺少主题型创意型空间等问题。；某大学图书馆王师傅以桌椅维修为主的木工工作，修抽屉、做木门、为古籍定制木箱、打磨卡窗户的小木块，在修缮中创造、于毫末处耕耘，为师生温暖笃定的生活秩序默默付出，展现平凡岗位的工匠精神。\nY市拟在总结江平县做法的基础上，提出关于加强 Y 市基层卫生人才队伍建设的实施意见。请根据「给定资料3」，起草该意见的主要内容。要求：包括指导思想、基本目标和主要措施；紧扣资料、重点突出；逻辑清晰、表述准确，不超过 450 字。", "req": "Y市拟在总结江平县做法的基础上，提出关于加强 Y 市基层卫生人才队伍建设的实施意见。请根据「给定资料3」，起草该意见的主要内容。要求：包括指导思想、基本目标和主要措施；紧扣资料、重点突出；逻辑清晰、表述准确，不超过 450 字。", "limit": "不超过300字", "points": [{"pt": "参考要点：一、指导思想——深入贯彻党的二十大精神，坚持以人民健康为中心，加强基层卫生人才队伍建设，提高基层医疗服务能力。二、基本目标——实现基层卫生人才规模、结", "n": 3}, {"pt": "建立健全人才培养机制，绩效考核、激励稳定现有人才、吸引人才加入", "n": 3}, {"pt": "加大培训力度，建实训示范基地、定期组织轮训", "n": 3}, {"pt": "加强与大医院合作，建远程会诊、影像诊断等中心", "n": 3}, {"pt": "创新人才使用机制，推行县管乡用、乡管村用", "n": 3}, {"pt": "出台优惠政策，提高待遇地位，确保人才引得进、留得住、用得好。", "n": 3}], "sample": "参考要点：一、指导思想——深入贯彻党的二十大精神，坚持以人民健康为中心，加强基层卫生人才队伍建设，提高基层医疗服务能力。二、基本目标——实现基层卫生人才规模、结构、能力与群众健康需求相适应，基层服务能力明显提升，看病难看病贵有效缓解。三、主要措施——①加强基层医疗机构建设，完善设备、提升环境；②建立健全人才培养机制，绩效考核、激励稳定现有人才、吸引人才加入；③加大培训力度，建实训示范基地、定期组织轮训；④加强与大医院合作，建远程会诊、影像诊断等中心；⑤创新人才使用机制，推行县管乡用、乡管村用；⑥出台优惠政策，提高待遇地位，确保人才引得进、留得住、用得好。", "tip": "综合分析题：先分层再压缩，每条“总括句＋具体做法”，不超字数、不漏分值点。"}]}, {"id": 6, "date": "2026-10-31", "range": "2026/10/26 – 2026/10/31", "title": "第 6 期周末测试 · 本周串考", "sub": "覆盖 2026/10/26 – 2026/10/31 本周考公（含本期常识/行测/词语速记）", "note": "行测 12 题交卷自动判分；申论 2 题交卷后对照踩分点自评。做题过程中不给答案、不给解析。", "xz": [{"date": "2026-10-31", "src": "issue", "no": 1, "mod": "常识判断", "type": "single", "stem": "习近平总书记指出，我们要建成的教育强国，是中国特色社会主义教育强国，应当具有强大的思政引领力、人才竞争力、科技支撑力、民生保障力、社会协同力、国际影响力，为以中国式现代化全面推进强国建设、民族复兴伟业提供有力支撑。关于建设教育强国，下列说法正确的是：", "options": ["要坚持教育均等化原则，把教育公平作为国家基本教育政策", "要完善人才培养与经济社会发展需要适配机制，顺应时代发展要求，适度增加学科专业数量", "要把引进全球顶尖科学家摆到更加突出位置，着力培育拔尖创新人才，推动实现高水平科技自立自强", "从教育大国到教育强国是一个系统性跃升和质变，必须以改革创新为动力"], "answer": ["D"], "explain": "逐项判断：A错误，2018年全国教育大会提出坚持教育公益性原则、把教育公平作为国家基本教育政策，不是'均等化'；B错误，2025年6月《求是》文章《加快建设教育强国》要求动态调整学科专业、优化办学资源配置，不是'适度增加专业数量'；C错误，要把培养国家重大战略急需人才摆到更加突出位置，不是'引进全球顶尖科学家'；D正确，2023年5月29日中央政治局第五次集体学习强调从教育大国到教育强国是系统性跃升和质变，必须以改革创新为动力", "tip": "易错点：A把'教育公益性原则'误记成'均等化'、B把'动态调整学科专业'误记成'适度增加专业数量'、C把'培养国家重大战", "key": "真题演练：D", "from": "第 1 期 · 本周常识"}, {"date": "2026-10-31", "src": "issue", "no": 2, "mod": "常识判断", "type": "single", "stem": "根据《中华人民共和国个人信息保护法》，下列说法不正确的是：", "options": ["个人发现其个人信息不准确或者不完整的，有权请求个人信息处理者更正、补充", "处理个人信息应当具有明确、合理的目的，并应当与处理目的直接相关，采取对个人权益影响最小的方式", "个人信息是以电子或者其他方式记录的与已识别或者可识别的自然人有关的各种信息，不包括匿名化处理后的信息", "基于个人同意处理个人信息的，个人有权撤回其同意。个人撤回同意，撤回前基于个人同意已进行的个人信息处理活动无效"], "answer": ["D"], "explain": "逐项判断：A个人发现信息不准确或不完整有权请求更正、补充，符合第四十六条，正确；B处理个人信息应目的明确合理、直接相关、采取对个人权益影响最小的方式，符合第六条，正确；C个人信息不包括匿名化处理后的信息，符合第四条，正确；D个人有权撤回同意，但撤回前基于同意已进行的处理活动依然有效，并非“无效”，说法错误", "tip": "易错点：误以为撤回同意后之前已处理的个人信息活动一律无效；记忆要点：个人撤回同意，不影响撤回前基于同意已进行的个人信息处", "key": "真题演练：D", "from": "第 2 期 · 本周常识"}, {"date": "2026-10-28", "src": "idiom", "no": 3, "mod": "言语理解与表达", "type": "single", "stem": "做学问要有____的胸襟。", "options": ["皮开肉绽", "杀鸡取卵", "海誓山盟", "海纳百川"], "answer": ["D"], "explain": "大海容得下众多河流；比喻胸怀宽广、包容一切，也指广泛吸收各种事物", "tip": "褒义，常与“有容乃大”连用", "key": "成语填空：海纳百川", "from": "第 3 期 · 词语速记"}, {"date": "2026-10-26", "src": "issue", "no": 4, "mod": "常识判断", "type": "single", "stem": "党的二十届三中全会提出，要稳步扩大制度型开放。关于稳步扩大制度型开放，下列举措不恰当的是：", "options": ["独立自主构建不同于国际经贸规则的中国特色经贸规则体系", "有序扩大我国商品市场、服务市场、资本市场、劳务市场等对外开放", "积极参与全球经济治理体系改革，提供更多全球公共产品", "扩大对最不发达国家单边开放"], "answer": ["A"], "explain": "逐项判断：A项错误，制度型开放要主动对接国际高标准经贸规则，在产权保护、产业补贴、环境标准等领域实现规则相通相容，而非独立自主构建“不同于”国际规则的体系；B项正确，有序扩大商品、服务、资本、劳务等市场对外开放；C项正确，积极参与全球经济治理体系改革，提供更多全球公共产品；D项正确，扩大对最不发达国家单边开放", "tip": "易错点：误以为制度型开放就是另起炉灶、自建一套规则。恰恰相反，制度型开放是主动对接国际高标准经贸规则，而非构建“不同于”", "key": "真题演练：A", "from": "第 4 期 · 本周常识"}, {"date": "2026-10-29", "src": "issue", "no": 5, "mod": "常识判断", "type": "single", "stem": "习近平总书记指出，要强化对市场主体的金融支持，发展普惠金融，有效缓解企业特别是中小微企业融资难融资贵问题。下列哪个措施最有助于新增融资重点流向中小微企业？", "options": ["深化市场报价利率改革，引导贷款利率继续下行", "探索优化教育、养老领域中长期融资的配套政策和运作模式", "综合运用清收、核销、重组、证券化、债转股等多种处置手段，大力化解不良资产风险", "银行业金融机构优先、快速对在中国人民银行征信报告中无贷款记录的企业提供贷款"], "answer": ["A"], "explain": "逐项判断：A对，深化LPR改革引导贷款利率继续下行，叠加再贷款再贴现资金发优惠利率贷款、支持信用贷款，能确保小微企业融资量增面扩价降，最直接让融资流向中小微；B错，教育养老领域中长期融资配套属优化金融体系、防范风险的安排，与中小微新增融资无直接关系；C错，清收核销重组证券化债转股是化解不良资产风险的手段，属存量风险处置，不是新增融资投放；D错，只针对“首贷”（征信报告中无贷款记录）企业，覆盖片面，不是最有助于整体流向中小微的措施", "tip": "易错点：把D“首贷企业”当成最普惠措施，其实首贷只覆盖征信无记录的那一小类，覆盖面窄；把B教育养老中长期融资、C不良资产", "key": "真题演练：A", "from": "第 5 期 · 本周常识"}, {"date": "2026-10-30", "src": "issue", "no": 6, "mod": "常识判断", "type": "single", "stem": "虚假诉讼、作伪证是我国重点打击的破坏司法秩序的行为。下列说法错误的是：", "options": ["甲伪造合同向法院起诉，意图获得非法利益，甲可能被罚款、拘留或被追究刑事责任", "甲指使乙在一民事案件中作伪证，甲的行为构成妨害作证罪", "甲欠乙2万元，因欠条遗失，乙补写欠条并模仿甲的签名后向法院起诉，乙的行为构成虚假诉讼罪", "甲为鉴定人，在某刑事案件中故意作虚假鉴定，意图陷害他人，甲的行为构成伪证罪"], "answer": ["C"], "explain": "逐项判断：A项正确，伪造证据妨碍审理可罚款、拘留直至追刑责；B项正确，指使他人作伪证构成妨害作证罪；C项错误，甲确欠乙2万元，乙虽补写欠条模仿签名，但债权债务真实，不存在“捏造事实”，不构成虚假诉讼罪；D项正确，刑事诉讼中鉴定人故意作虚假鉴定意图陷害构成伪证罪", "tip": "易错点：误以为补写欠条起诉就构成虚假诉讼罪。虚假诉讼罪要求“捏造事实”，而本题甲确实欠乙2万元，债务真实存在，不构成“捏", "key": "真题演练：C", "from": "第 6 期 · 本周常识"}, {"date": "2026-10-28", "src": "xc", "no": 7, "mod": "科学推理", "type": "single", "stem": "在生活中，我们可以用紫色的蝴蝶兰花溶液作为酸碱指示剂，其遇酸性溶液显红色，遇碱性溶液则显黄色。下列说法正确的是（ ）。", "options": ["在盐水中滴入蝴蝶兰花溶液，溶液呈红色", "在纯净水中滴入蝴蝶兰花溶液，溶液呈无色", "在苏打水中滴入蝴蝶兰花溶液，溶液呈黄色", "在酸或碱性溶液滴入蝴蝶兰花溶液后，变色的过程属于物理变化"], "answer": ["C"], "explain": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "tip": "易错点：误以为中性溶液会让指示剂“无色”，或把指示剂变色当成物理变化；遇酸碱发生的是化学变化。", "key": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，", "from": "第 7 批 · 行测加练"}, {"date": "2026-10-26", "src": "xc", "no": 8, "mod": "数量关系", "type": "single", "stem": "小张每周一到周四夜跑，周五到周日休息，已知某年2月他夜跑17次，3月夜跑19次，问4月他夜跑多少次？", "options": ["16", "17", "18", "19"], "answer": ["A"], "explain": "思路：周期+星期推断。详解：每周跑周一至周四共4次，连续28天跑16次。2月前28天跑16次，实际17次，多出1次，故该年2月有29天（闰年），2月29日为跑步日。3月31天，后28天跑16次，前3天（3月1—3日）跑19-16=3次，即2月29日至3月3日连续4天都跑，只能是周一至周四，故3月3日为周四、4月1日为周五。4月30天，前28天跑16次，最后两天4月29、30日为周五、周六休息，故4月跑16次。故答案为A。", "tip": "易错点：误判2月为平年28天，或排星期时把连续4个跑步日对应错。陷阱：连续28天固定跑16次，多出的次数用来推星期几和闰年。", "key": "思路：周期+星期推断。详解：每周跑周一至周四共4次，连续28天跑16次。2月前2", "from": "第 8 批 · 行测加练"}, {"date": "2026-10-26", "src": "xc", "no": 9, "mod": "判断推理", "type": "single", "stem": "经：史：子：集", "options": ["风：雅：颂", "仁：义：礼：智", "浑：元：盎：宋", "农：医：兵：艺"], "answer": ["C"], "explain": "先定一级关系：经、史、子、集是古代图书的四大并列类目。二级辨析：A风雅颂仅三类，数量与性质不符；B仁义礼智是儒家四德，虽四项但非图书/历史类目；C浑、元、盎、宋是按时间排列的并列时期，与“四个并列类目”二级最贴近；D农医兵艺是并列技艺门类但结构不如C。当选C。", "tip": "易错点：误选A（风：雅：颂）。一级：经史子集是我国古代图书四部分类，四个并列类目。二级要找同为四个并列历史分期/分类的项。浑源、元、盎、宋是中国历史上的四个时期", "key": "先定一级关系：经、史、子、集是古代图书的四大并列类目。二级辨析：A风雅颂仅三类，", "from": "第 9 批 · 行测加练"}, {"date": "2026-10-28", "src": "issue", "no": 10, "mod": "常识判断", "type": "single", "stem": "下列与古人出行有关的说法错误的是：", "options": ["“开远门前万里堠”中的“堠”是一种路标，可以用来导航和计程", "“乘舟而惑者，不知东西，见斗极则寤矣”中的“极”就是北极星", "“东有启明，西有长庚”中指示方向的“启明”“长庚”是不同天体", "“过洋牵星术”是通过测量星辰的高度指数来确定船只所处位置的"], "answer": ["C"], "explain": "逐项判断：A正确，\"堠\"是古代官道旁每隔一段距离堆的石堆或土堆路标，既可指明道路走向又可计程；B正确，\"乘舟而惑者，不知东西，见斗极则寤矣\"出自《淮南子》，\"极\"指北极星，与北斗一起用于水路辨别方向；C错误，\"东有启明，西有长庚\"出自《大东》，启明和长庚都是金星，金星轨道在地球之内，日出前见于东方叫启明星、日落后见于西方叫长庚星，是同一天体；D正确，过洋牵星术是中国古代航海天文导航技术，用牵星板测量星辰高度计算地理纬度来测定船只位置", "tip": "易错点：C项误以为启明和长庚是不同天体，实际都是金星，只是日出前见于东方叫启明星、日落后见于西方叫长庚星。记忆要点：启明", "key": "真题演练：C", "from": "第 10 期 · 本周常识"}, {"date": "2026-10-28", "src": "idiom", "no": 11, "mod": "言语理解与表达", "type": "single", "stem": "他____地锻炼，身体越来越好。", "options": ["坚持不懈", "家徒四壁", "浅尝辄止", "寄人篱下"], "answer": ["A"], "explain": "懈：松懈。坚持到底，毫不松懈", "tip": "“懈”读 xiè，意为松懈；褒义", "key": "成语填空：坚持不懈", "from": "第 11 期 · 词语速记"}, {"date": "2026-10-29", "src": "xc", "no": 12, "mod": "判断推理", "type": "single", "stem": "日前，研究人员发明了一种弹性超强的新材料，这种材料可以由1英寸被拉伸到100英寸以上，同时这一材料可以自行修复且能通过电压控制动作。因此研究者认为，利用该材料可以制成人工肌肉，替代人体肌肉，从而为那些肌肉损伤后无法恢复功能的患者带来福音。 以下哪项如果为真，不能支持研究者的观点？", "options": ["该材料制成的人工肌肉在受到破坏或损伤后能立即启动修复机制，比正常肌肉的康复速度快", "该材料在电刺激下会发生膨胀或收缩，具有良好的柔韧性，与正常肌肉十分接近", "目前，该材料研制成的人工肌肉尚不能与人体神经很好的契合，无法实现精准抓取物体等动作", "一般材料如果被破坏，需通过溶剂修复或热修复复原，而该材料在室温下就能自行恢复"], "answer": ["C"], "explain": "第一步：找出论点和论据。 论点：利用弹性超强的新材料可以制成人工肌肉，替代人体肌肉，从而为那些肌肉损伤后无法恢复功能的患者带来福音。 论据：研究人员发明了一种弹性超强的新材料，这种材料可以由1英寸被拉伸到100英寸以上，同时这一材料可以自行修复且能通过电压控制动作。 第二步：逐一分析选项。 A项：该材料制成的人工肌肉比正常肌肉的康复速度快。说明这种新材料制成的人工肌肉确实给那些肌肉损伤后无法恢复功能的患者带来了福音，通过补充论据的方式加强了题干论点，排除； B项：该材料制成的人工肌肉具有良好的柔韧性，与正常肌肉十分接近。说明用人工肌肉替代人体肌肉是可行的，可以给那些肌肉损伤后无法恢复功能的患者带来福音，通过补充论据的方式加强了题干论点，排除； C项：人工肌肉尚不能与人体神经很好的契合，无法实现精准抓取物体等动作。这说明用人工肌肉替代人体肌肉不可行，不能完成正常的人体动作。该项可以削弱论点，不能加强，当选； D项：该材料在室温下就能自行恢复，说明用人工肌肉替代人体肌肉是可行的，即使损坏，也可以自行修复。这就给那些肌肉损伤后无法恢复功能的患者带来福音，通过补充论据的方式加强了题干论点，排除。 本题为选非题，⇒ 正确答案为C。", "tip": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "key": "第一步：找出论点和论据。 论点：利用弹性超强的新材料可以制成人工肌肉，替代人体肌", "from": "第 12 批 · 行测加练"}], "sl": [{"no": 1, "mod": "文章写作", "from": "申论真题 · 国考", "stem": "【真题材料摘要】G市工业大学冯教授团队入驻桃李镇清池村，以「与村民一起动手」代替授课，从建大椅子、家庭美术馆起步，重新挖掘「烧奔塔」「成人礼」等传统习俗，举办乡村时装秀。主张以「膜拜」而非「治理教导」的心态介入乡村，探索「超越艺术」的路径，当好挖掘本土文化特色的「运营官」。；N市隆金公司专注汽车门把手等配件，2012年起每年投入数千万元建设全自动数字化车间，依托企业研究院、海外研发中心、产学研合作吸引创新人才，近三年完成研发项目超300项、专利295项，95%产品实现国产化替代，迈入「单项冠军」方阵。；J省江平县曾面临乡镇卫生院人才奇缺困境，通过稳定现有人才、绩效考核拉开收入差距、急缺人才现场考试招录、购房补贴、偏远乡镇补助、编制周转池、县管乡用乡管村用、实训基地轮训、与三甲医院共建院士工作站和远程会诊中心等举措破解基层医疗人才难题。；S市涌现一批公共文化空间：畅雅艺术空间辐射6200居民、活动火爆；但不少民营美术馆、24小时书院冷冷清清；大型实体书店场景营造同质化、审美疲劳；市美术馆被当「网红打卡点」；同时存在载体规模偏小、布局分散、缺少主题型创意型空间等问题。；某大学图书馆王师傅以桌椅维修为主的木工工作，修抽屉、做木门、为古籍定制木箱、打磨卡窗户的小木块，在修缮中创造、于毫末处耕耘，为师生温暖笃定的生活秩序默默付出，展现平凡岗位的工匠精神。\n「给定资料5」中提到：「投入自己的领域，不断『打磨』、不断『修补』，为人们温暖笃定的生活秩序默默付出，稳步前行。」请根据对这句话的理解，参考给定资料，联系实际，自选角度，自拟题目，写一篇文章。要求：观点明确、见解深刻；参考给定资料但不拘泥于给定资料；思路清晰、语言流畅；字数 1000-1200 字。", "req": "「给定资料5」中提到：「投入自己的领域，不断『打磨』、不断『修补』，为人们温暖笃定的生活秩序默默付出，稳步前行。」请根据对这句话的理解，参考给定资料，联系实际，自选角度，自拟题目，写一篇文章。要求：观点明确、见解深刻；参考给定资料但不拘泥于给定资料；思路清晰、语言流畅；字数 1000-1200 字。", "limit": "不超过300字", "points": [{"pt": "写作思路参考：中心论点——在平凡岗位上以匠心打磨、以行动修补，为生活秩序默默付出，本身就是不凡的价值创造。分论点示例：①匠心在于对品质的坚守——于细微处见真章（", "n": 11}, {"pt": "行动在于对责任的担当——小补丁也有大意义（一扇木门、一个窗卡背后是被重视被关怀的人）", "n": 11}, {"pt": "平凡可以成就非凡——每一个默默付出的人共同支撑社会的温暖秩序。可联系工匠精神、基层治理、为民服务等角度展开。", "n": 11}], "sample": "写作思路参考：中心论点——在平凡岗位上以匠心打磨、以行动修补，为生活秩序默默付出，本身就是不凡的价值创造。分论点示例：①匠心在于对品质的坚守——于细微处见真章（王师傅修椅子、做木箱、打磨小木块）；②行动在于对责任的担当——小补丁也有大意义（一扇木门、一个窗卡背后是被重视被关怀的人）；③平凡可以成就非凡——每一个默默付出的人共同支撑社会的温暖秩序。可联系工匠精神、基层治理、为民服务等角度展开。", "tip": "综合分析题：先分层再压缩，每条“总括句＋具体做法”，不超字数、不漏分值点。"}, {"no": 2, "mod": "综合分析", "from": "申论真题 · 国考", "stem": "【真题材料摘要】A市把科技创新摆在核心位置，成立5个市级科技成果转化专班，常态化登门入室对接高校院所，做好成果发现、挖掘、策划、转化；依托龙腾工业互联网平台推动项目落地、产业链供需互促，帮助「硬核」科技加快转化为新质生产力。；S市总工会通过「连心桥」小程序开展职工心声大调查、设置吐槽专区，推动各单位迅速改进；12351职工维权服务热线成为「连心线」；智慧工会平台发放清凉券惠及户外工作者；打造「五星」工会服务站点，「一站一品」式特色化运营精准回应劳动者诉求。；B市公安局大帆分局联合多部门成立夜市综合服务办公室，制定安全管理规定，公安、城管、市场监管、街道人员组成巡查小组分组定时巡查：检查消防灭火器、用电、食品安全，发现问题上传市场管理平台、开具限期整改通知书；处置车辆违停、调解纠纷、寻找走失儿童；平安驿站开展反诈宣传等。；指导组到某企业检查危险废物管理：仓库实行双人双锁、分类标签、围堰防渗等措施较完善，但发现部分危险废物未贴标签、散落废包装物，台账未按种类单独成册、流向信息缺失、电子版与纸质版不一致；企业委托专业处置单位并签订合同，固体废物安全处理率待提高。；C市医疗保障局开设全天候办理窗口，实行轮岗和双休日办公；税务部门与银行、社区、园区共建税费服务驿站，15分钟办税圈延伸至偏远地区，设远程虚拟窗口在线协同办税；雨霞区设立「办不成事窗口」，倒逼干部担当作为，实现事事有着落、件件有回音。\n结合「给定资料2」，谈谈你对 M 社区「网格执法+柔性劝导」模式的理解。（依据网友回忆版整理，作答要点围绕工会服务职工、精准回应诉求展开）要求：观点明确、分析透彻、条理清晰，不超过 300 字。", "req": "结合「给定资料2」，谈谈你对 M 社区「网格执法+柔性劝导」模式的理解。（依据网友回忆版整理，作答要点围绕工会服务职工、精准回应诉求展开）要求：观点明确、分析透彻、条理清晰，不超过 300 字。", "limit": "不超过300字", "points": [{"pt": "该模式的核心是以职工需求推动服务、以精准对接取代单向灌输：①数字赋能，通过「连心桥」小程序、智慧工会平台收集意见建议、发放清凉券，把服务送到职工指尖", "n": 6}, {"pt": "阵地升级，通过「星级」站点创建、「一站一品」特色化运营，精准回应户外劳动者和新就业形态劳动者的工作生活诉求", "n": 6}, {"pt": "服务闭环，从心声收集到问题整改形成快速反馈机制。启示：柔性服务要贴近对象、整合资源、闭环管理，把「送服务」变为「共治理」。", "n": 6}], "sample": "该模式的核心是以职工需求推动服务、以精准对接取代单向灌输：①数字赋能，通过「连心桥」小程序、智慧工会平台收集意见建议、发放清凉券，把服务送到职工指尖；②阵地升级，通过「星级」站点创建、「一站一品」特色化运营，精准回应户外劳动者和新就业形态劳动者的工作生活诉求；③服务闭环，从心声收集到问题整改形成快速反馈机制。启示：柔性服务要贴近对象、整合资源、闭环管理，把「送服务」变为「共治理」。", "tip": "综合分析题：先分层再压缩，每条“总括句＋具体做法”，不超字数、不漏分值点。"}]}, {"id": 7, "date": "2026-10-31", "range": "2026/10/26 – 2026/10/31", "title": "第 7 期周末测试 · 本周串考", "sub": "覆盖 2026/10/26 – 2026/10/31 本周考公（含本期常识/行测/词语速记）", "note": "行测 12 题交卷自动判分；申论 2 题交卷后对照踩分点自评。做题过程中不给答案、不给解析。", "xz": [{"date": "2026-10-31", "src": "issue", "no": 1, "mod": "常识判断", "type": "single", "stem": "习近平总书记指出：“中国共产党人的理想信念，建立在马克思主义科学真理的基础之上，建立在马克思主义揭示的人类社会发展规律的基础之上，建立在为最广大人民谋利益的崇高价值的基础之上。我们坚定，是因为我们追求的是真理。我们坚定，是因为我们遵循的是规律。我们坚定，是因为我们代表的是最广大人民根本利益。”这一论述最直接体现了马克思主义的哪一基本观点？", "options": ["真理尺度与价值尺度的辩证统一", "认识世界与改造世界的辩证统一", "量变与质变的辩证统一", "矛盾的特殊性与普遍性的辩证统一"], "answer": ["A"], "explain": "逐项判断：A项正确，“建立在科学真理、人类社会发展规律基础上”体现真理尺度，“为最广大人民谋利益、代表人民根本利益”体现价值尺度，二者辩证统一；B项错误，题干未涉及认识世界与改造世界的关系；C项错误，题干无量变质变内容；D项错误，题干未体现共性个性关系", "tip": "易错点：只看到“追求真理、遵循规律”就误选认识论或矛盾观，忽略后半句“为最广大人民谋利益、代表人民根本利益”的价值维度。", "key": "真题演练：A", "from": "第 1 期 · 本周常识"}, {"date": "2026-10-31", "src": "xc", "no": 2, "mod": "数量关系", "type": "single", "stem": "小王和小李同时从山脚A点出发匀速登山，小王距山顶还有路程时小李刚走完上山路程的，小王到达山顶后立即原路返回，10分钟后遇到上山途中的小李。已知两人下山的速度为各自上山速度的1.5倍，问小李比小王晚多少分钟到达山脚A点？", "options": ["30", "40", "50", "60"], "answer": ["C"], "explain": "思路：比例法+赋值。详解：相同时刻小王走了7/8路程、小李走了1/3路程，速度比v王:v李=(7/8):(1/3)=21:8，赋值v王=8、v李=6。下山速度：王=8×1.5=12，李=6×1.5=9。设总路程24S，小王到山顶时小李距山顶还有24S×(1-6/8)=6S。小王下山10分钟遇小李（小李仍在上山，速度6）：6S=(6+12)×10=180，解得S=30，总路程=24×30=720。小王往返时间=720/8+720/12=90+60=150分钟；小李往返时间=720/6+720/9=120+80=200分钟。相差200-150=50分钟。故答案为C。", "tip": "易错点：速度比搞反；或忘记下山速度是上山1.5倍；相遇时两人路程关系列错。", "key": "思路：比例法+赋值。详解：相同时刻小王走了7/8路程、小李走了1/3路程，速度比", "from": "第 2 批 · 行测加练"}, {"date": "2026-10-26", "src": "xc", "no": 3, "mod": "科学推理", "type": "single", "stem": "胰岛素是一种蛋白质，可以用于治疗糖尿病。以下有关胰岛素的说法，正确的是（ ）。", "options": ["胰岛素能够抑制血糖分解", "人体中的胰岛素由肝脏分泌", "一般通过口服胰岛素治疗糖尿病", "血液中的胰岛素浓度过高会导致低血糖"], "answer": ["D"], "explain": "思路：结合胰岛素的化学本质、分泌部位和作用判断；详解：A胰岛素是促进血糖合成糖原、降低血糖，不是抑制血糖分解；B由胰岛（胰腺内分泌部）分泌；C蛋白质口服会被消化，须注射；D胰岛素降血糖，浓度过高会使血糖过低。故答案为D。", "tip": "易错点：以为胰岛素口服有效；胰岛素是蛋白质，口服会被消化道分解失效，只能注射；它由胰岛分泌而非肝脏。", "key": "思路：结合胰岛素的化学本质、分泌部位和作用判断；详解：A胰岛素是促进血糖合成糖原", "from": "第 3 批 · 行测加练"}, {"date": "2026-10-31", "src": "issue", "no": 4, "mod": "常识判断", "type": "single", "stem": "下列与生物灾害有关的说法错误的是：", "options": ["中国蝗灾最严重的地区是两湖地区", "稻飞虱的天敌有蜘蛛、青蛙", "松毛虫在高温干旱环境下更易繁殖", "鼠类会啃食庄稼的茎、叶、根和种子"], "answer": ["A"], "explain": "逐项判断：A错，蝗灾由干旱引发，我国历史蝗灾集中分布在今河北、河南、山东三省，两湖地区较湿润，不是蝗灾最严重地区；B对，稻飞虱是水稻重要害虫，天敌包括捕食性的蜘蛛、青蛙和寄生性的缨小蜂、白僵菌等；C对，松毛虫繁殖力强，高温干旱是其大规模暴发的最重要诱因之一；D对，鼠类杂食，啃食庄稼地下根茎，也吃地上茎叶、种子和储存农产品", "tip": "易错点：把蝗灾重灾区误记为湿润的两湖地区，实则蝗灾由干旱引起，我国蝗灾最严重是河北、河南、山东等华北省份；记忆要点：蝗灾", "key": "真题演练：A", "from": "第 4 期 · 本周常识"}, {"date": "2026-10-30", "src": "idiom", "no": 5, "mod": "言语理解与表达", "type": "single", "stem": "他只会____，真要做事实在一塌糊涂。", "options": ["要言不烦", "强词夺理", "夸夸其谈", "华而不实"], "answer": ["C"], "explain": "形容说话浮夸，滔滔不绝却不切实际。", "tip": "含贬义，指空谈而不实干，须与中性或褒义的“侃侃而谈”区分。", "key": "成语填空：夸夸其谈", "from": "第 5 期 · 词语速记"}, {"date": "2026-10-31", "src": "issue", "no": 6, "mod": "常识判断", "type": "single", "stem": "在2023年7月召开的全国生态环境保护大会上，习近平总书记全面总结我国生态文明建设取得的举世瞩目的巨大成就，精辟概括了“四个重大转变”，这四个重大转变是： ①实现由重点整治到系统治理的重大转变 ②实现由被动应对到主动作为的重大转变 ③实现由全球环境治理参与者到引领者的重大转变 ④实现由实践探索到科学理论指导的重大转变 ⑤实现由多重压力叠加到单一结构性压力的重大转变", "options": ["①②③④", "①②③⑤", "②③④⑤", "①③④⑤"], "answer": ["A"], "explain": "逐项判断：①由重点整治到系统治理，正确；②由被动应对到主动作为，正确；③由全球环境治理参与者到引领者，正确；④由实践探索到科学理论指导，正确；⑤错误，“多重压力叠加”并非向“单一结构性压力”转变，无出处", "tip": "易错点：⑤把压力转变方向误认正确，实则“四个重大转变”不含⑤，该项属编造表述。记忆要点：四个转变=重点整治→系统治理、被", "key": "真题演练：A", "from": "第 6 期 · 本周常识"}, {"date": "2026-10-31", "src": "issue", "no": 7, "mod": "常识判断", "type": "single", "stem": "下列与急救有关的说法正确的是：", "options": ["误服氨水者应该立即进行洗胃或催吐", "农药沾染皮肤中毒可立即用热水擦洗", "误食强酸可以立即口服氢氧化铝凝胶", "烧伤时应立即饮用大量凉水补充体液"], "answer": ["C"], "explain": "逐项判断：A错，误服氨水应漱口、口服稀释醋或柠檬汁并就医，切忌催吐、洗胃，以免食道胃穿孔；B错，农药沾染皮肤应脱去污染衣物、用肥皂水或流动清水冲洗，不能用热水（热水升温扩孔加速吸收）；C对，误食强酸可口服3%-4%氢氧化铝凝胶（或蛋清、牛奶）保护食管胃黏膜；D错，烧伤应少量多次饮凉水（可加少量盐、小苏打补充电解质），不能一次性大量饮用以免水肿", "tip": "易错点：①误以为误服氨水要催吐洗胃（反而致穿孔）；②误以为农药中毒用热水洗（热水扩张毛孔加速吸收）；④误以为烧伤要大量喝", "key": "真题演练：C", "from": "第 7 期 · 本周常识"}, {"date": "2026-10-31", "src": "issue", "no": 8, "mod": "常识判断", "type": "single", "stem": "高质量发展是全面建设社会主义现代化国家的首要任务，金融要为经济社会发展提供高质量服务。下列与之相关的表述不准确的是：", "options": ["优化资金供给结构，把更多金融资源用于促进科技创新、绿色发展、传统制造和国有企业", "要着力营造良好的货币金融环境，切实加强对重大战略、重点领域和薄弱环节的优质金融服务", "始终保持货币政策的稳健性，更加注重做好跨周期和逆周期调节，充实货币政策工具箱", "完善机构定位，支持国有大型金融机构做优做强，当好服务实体经济的主力军和维护金融稳定的压舱石"], "answer": ["A"], "explain": "逐项判断：A项错误，中央金融工作会议提出把更多金融资源用于促进科技创新、先进制造、绿色发展和中小微企业，而非“传统制造和国有企业”；B项正确，要营造良好货币金融环境，加强对重大战略、重点领域和薄弱环节的优质金融服务；C项正确，保持货币政策稳健，注重跨周期和逆周期调节，充实政策工具箱；D项正确，支持国有大型金融机构做优做强，当好服务实体经济主力军和维护金融稳定压舱石", "tip": "易错点：把“先进制造、中小微企业”误记为“传统制造、国有企业”，被选项的并列搭配偷换。记忆要点：金融资源投向是科技创新、", "key": "真题演练：A", "from": "第 8 期 · 本周常识"}, {"date": "2026-10-30", "src": "xc", "no": 9, "mod": "判断推理", "type": "single", "stem": "流感病毒的变异速度相当快，即使疫苗每年更新，也不能保证疫苗接种覆盖全部的“当季流行款”。接种流感疫苗，既不能保证百分之百不得流感，还可能导致接种人群出现低烧等副作用。因此，没有必要接种流感疫苗。 以下选项如果为真，不能有效反驳上文结论的是：", "options": ["接种流感疫苗可以减少儿童、慢性病患者等高危人群因流感而发生严重并发症的风险", "接种季节性流感疫苗可以降低易感人群感染流感病毒的概率", "接种流感疫苗后只有极少数人会出现全身反应，且一两天可以缓解，比流感的症状要轻很多", "从疾病中恢复过来的人可以获得一定的免疫力，1年内不会再次被同样的流感病毒感染"], "answer": ["D"], "explain": "第一步：找到论点和论据。 论点：没有必要接种流感疫苗。 论据：接种流感疫苗，不仅不能保证百分之百不得流感，还可能导致低烧等副作用。 第二步：逐一分析选项。 A项：接种流感疫苗可以减少儿童、慢性病患者等高危人群因流感而发生严重并发症的风险，说明接种流感疫苗是有好处的，是有必要的，削弱论点，排除； B项：接种季节性流感疫苗可以降低易感人群感染流感病毒的概率，说明接种流感疫苗是有好处的，是有必要的，削弱论点，排除； C项：接种流感疫苗只有极少数人会出现全身反应，说明出现反应的概率特别小，而且反应一两天就可以缓解，症状比流感症状轻得多，产生的副作用也较小，削弱论据，排除； D项：从疾病中恢复过来的人，1年不会再次被同样的流感病毒感染，只能说明疾病中恢复过来的人可能1年内不需要接种某种流感疫苗，与是否需要接种其他的流感疫苗无关，属于无关选项，当选。 本题为选非题，⇒ 正确答案为D。", "tip": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "key": "第一步：找到论点和论据。 论点：没有必要接种流感疫苗。 论据：接种流感疫苗，不仅", "from": "第 9 批 · 行测加练"}, {"date": "2026-10-30", "src": "idiom", "no": 10, "mod": "言语理解与表达", "type": "single", "stem": "同学们____地讨论着春游计划。", "options": ["藕断丝连", "千军万马", "七嘴八舌", "前功尽弃"], "answer": ["C"], "explain": "形容人多口杂，议论纷纷", "tip": "侧重议论杂乱，多含轻微贬义", "key": "成语填空：七嘴八舌", "from": "第 10 期 · 词语速记"}, {"date": "2026-10-28", "src": "xc", "no": 11, "mod": "图形推理", "type": "single", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "图形的方向依次顺时针旋转。", "tip": "图形推理：先观察元素组成、数量与位置规律，再验证选项。", "key": "图形推理：对称/数量/位置规律。", "from": "第 11 批 · 行测加练"}, {"date": "2026-10-31", "src": "issue", "no": 12, "mod": "常识判断", "type": "single", "stem": "习近平总书记指出：“宪法作为上层建筑，一定要适应经济基础的变化而变化。任何国家都不可能制定一部永远适用的宪法。”下列古语与这一观点最为契合的是（ ）。", "options": ["理国要道，在于公平正直", "法与时转则治，治与世宜则有功", "盖天下之事，不难于立法，而难于法之必行", "举直错诸枉，则民服；举枉错诸直，则民不服"], "answer": ["B"], "explain": "逐项判断：A“理国要道，在于公平正直”出自《贞观政要》，讲治理国家贵在公平正义，属执政理念，未体现“法随时代变”，不合；B“法与时转则治，治与世宜则有功”出自《韩非子·心度》，意为法度随时代发展而调整、治理方式与社会实际相适配才能成功，正好对应“宪法要适应经济基础变化”，当选；C“不难于立法，而难于法之必行”张居正语，强调法律贵在执行落实，不合；D“举直错诸枉”出自《论语》，讲任人唯贤、用人导向，不合", "tip": "易错点：只看“法”字就乱选，没抓住题干“上层建筑随经济基础变化而变化”即法律要与时俱进的核心；记忆要点：题干讲的是法律制", "key": "真题演练：B", "from": "第 12 期 · 本周常识"}], "sl": [{"no": 1, "mod": "文章写作", "from": "申论真题 · 国考", "stem": "【真题材料摘要】A市把科技创新摆在核心位置，成立5个市级科技成果转化专班，常态化登门入室对接高校院所，做好成果发现、挖掘、策划、转化；依托龙腾工业互联网平台推动项目落地、产业链供需互促，帮助「硬核」科技加快转化为新质生产力。；S市总工会通过「连心桥」小程序开展职工心声大调查、设置吐槽专区，推动各单位迅速改进；12351职工维权服务热线成为「连心线」；智慧工会平台发放清凉券惠及户外工作者；打造「五星」工会服务站点，「一站一品」式特色化运营精准回应劳动者诉求。；B市公安局大帆分局联合多部门成立夜市综合服务办公室，制定安全管理规定，公安、城管、市场监管、街道人员组成巡查小组分组定时巡查：检查消防灭火器、用电、食品安全，发现问题上传市场管理平台、开具限期整改通知书；处置车辆违停、调解纠纷、寻找走失儿童；平安驿站开展反诈宣传等。；指导组到某企业检查危险废物管理：仓库实行双人双锁、分类标签、围堰防渗等措施较完善，但发现部分危险废物未贴标签、散落废包装物，台账未按种类单独成册、流向信息缺失、电子版与纸质版不一致；企业委托专业处置单位并签订合同，固体废物安全处理率待提高。；C市医疗保障局开设全天候办理窗口，实行轮岗和双休日办公；税务部门与银行、社区、园区共建税费服务驿站，15分钟办税圈延伸至偏远地区，设远程虚拟窗口在线协同办税；雨霞区设立「办不成事窗口」，倒逼干部担当作为，实现事事有着落、件件有回音。\n请你对「给定资料5」中提到的「为群众办好事」「让群众感到好办事」「把群众的事办好」进行深入系统的思考，联系实际，自拟题目，写一篇文章。要求：观点明确、见解深刻、内容充实；参考给定资料但不拘泥于给定资料；思路清晰、语言流畅；字数 1000-1200 字。", "req": "请你对「给定资料5」中提到的「为群众办好事」「让群众感到好办事」「把群众的事办好」进行深入系统的思考，联系实际，自拟题目，写一篇文章。要求：观点明确、见解深刻、内容充实；参考给定资料但不拘泥于给定资料；思路清晰、语言流畅；字数 1000-1200 字。", "limit": "不超过300字", "points": [{"pt": "写作思路参考：中心论点——政务服务要以群众需求为标尺，既办好「具体事」，又让群众「办得顺心」，真正把群众的事办好。分论点示例：①「办好事」是出发点——主动发现需", "n": 11}, {"pt": "「好办事」是方法论——流程再造、数字赋能，让办事省时省力（一窗受理、远程虚拟窗口、15分钟办税圈）", "n": 11}, {"pt": "「把事办好」是落脚点——建章立制、兜底担当，事事有着落件件有回音（办不成事窗口倒逼干部担当）。可联系行政执法、基层治理、服务型政府等角度。", "n": 11}], "sample": "写作思路参考：中心论点——政务服务要以群众需求为标尺，既办好「具体事」，又让群众「办得顺心」，真正把群众的事办好。分论点示例：①「办好事」是出发点——主动发现需求，把服务送到群众家门口（全天候窗口、税费服务驿站进街道）；②「好办事」是方法论——流程再造、数字赋能，让办事省时省力（一窗受理、远程虚拟窗口、15分钟办税圈）；③「把事办好」是落脚点——建章立制、兜底担当，事事有着落件件有回音（办不成事窗口倒逼干部担当）。可联系行政执法、基层治理、服务型政府等角度。", "tip": "综合分析题：先分层再压缩，每条“总括句＋具体做法”，不超字数、不漏分值点。"}, {"no": 2, "mod": "综合分析", "from": "申论真题 · 国考", "stem": "【真题材料摘要】A市把科技创新摆在核心位置，成立5个市级科技成果转化专班，常态化登门入室对接高校院所，做好成果发现、挖掘、策划、转化；依托龙腾工业互联网平台推动项目落地、产业链供需互促，帮助「硬核」科技加快转化为新质生产力。；S市总工会通过「连心桥」小程序开展职工心声大调查、设置吐槽专区，推动各单位迅速改进；12351职工维权服务热线成为「连心线」；智慧工会平台发放清凉券惠及户外工作者；打造「五星」工会服务站点，「一站一品」式特色化运营精准回应劳动者诉求。；B市公安局大帆分局联合多部门成立夜市综合服务办公室，制定安全管理规定，公安、城管、市场监管、街道人员组成巡查小组分组定时巡查：检查消防灭火器、用电、食品安全，发现问题上传市场管理平台、开具限期整改通知书；处置车辆违停、调解纠纷、寻找走失儿童；平安驿站开展反诈宣传等。；指导组到某企业检查危险废物管理：仓库实行双人双锁、分类标签、围堰防渗等措施较完善，但发现部分危险废物未贴标签、散落废包装物，台账未按种类单独成册、流向信息缺失、电子版与纸质版不一致；企业委托专业处置单位并签订合同，固体废物安全处理率待提高。；C市医疗保障局开设全天候办理窗口，实行轮岗和双休日办公；税务部门与银行、社区、园区共建税费服务驿站，15分钟办税圈延伸至偏远地区，设远程虚拟窗口在线协同办税；雨霞区设立「办不成事窗口」，倒逼干部担当作为，实现事事有着落、件件有回音。\n结合「给定资料2」，谈谈你对 M 社区「网格执法+柔性劝导」模式的理解。（依据网友回忆版整理，作答要点围绕工会服务职工、精准回应诉求展开）要求：观点明确、分析透彻、条理清晰，不超过 300 字。", "req": "结合「给定资料2」，谈谈你对 M 社区「网格执法+柔性劝导」模式的理解。（依据网友回忆版整理，作答要点围绕工会服务职工、精准回应诉求展开）要求：观点明确、分析透彻、条理清晰，不超过 300 字。", "limit": "不超过300字", "points": [{"pt": "该模式的核心是以职工需求推动服务、以精准对接取代单向灌输：①数字赋能，通过「连心桥」小程序、智慧工会平台收集意见建议、发放清凉券，把服务送到职工指尖", "n": 6}, {"pt": "阵地升级，通过「星级」站点创建、「一站一品」特色化运营，精准回应户外劳动者和新就业形态劳动者的工作生活诉求", "n": 6}, {"pt": "服务闭环，从心声收集到问题整改形成快速反馈机制。启示：柔性服务要贴近对象、整合资源、闭环管理，把「送服务」变为「共治理」。", "n": 6}], "sample": "该模式的核心是以职工需求推动服务、以精准对接取代单向灌输：①数字赋能，通过「连心桥」小程序、智慧工会平台收集意见建议、发放清凉券，把服务送到职工指尖；②阵地升级，通过「星级」站点创建、「一站一品」特色化运营，精准回应户外劳动者和新就业形态劳动者的工作生活诉求；③服务闭环，从心声收集到问题整改形成快速反馈机制。启示：柔性服务要贴近对象、整合资源、闭环管理，把「送服务」变为「共治理」。", "tip": "综合分析题：先分层再压缩，每条“总括句＋具体做法”，不超字数、不漏分值点。"}]}, {"id": 8, "date": "2026-10-31", "range": "2026/10/26 – 2026/10/31", "title": "第 8 期周末测试 · 本周串考", "sub": "覆盖 2026/10/26 – 2026/10/31 本周考公（含本期常识/行测/词语速记）", "note": "行测 12 题交卷自动判分；申论 2 题交卷后对照踩分点自评。做题过程中不给答案、不给解析。", "xz": [{"date": "2026-10-31", "src": "idiom", "no": 1, "mod": "言语理解与表达", "type": "single", "stem": "这家老字号____，顾客盈门。", "options": ["筑室道谋", "对簿公堂", "戛然而止", "久负盛名"], "answer": ["D"], "explain": "负：享有。长久以来享有很高的名声", "tip": "“负”此处读 fù，意为享有；褒义", "key": "成语填空：久负盛名", "from": "第 1 期 · 词语速记"}, {"date": "2026-10-31", "src": "issue", "no": 2, "mod": "常识判断", "type": "single", "stem": "根据《中华人民共和国社会保险法》，下列说法不正确的是：", "options": ["治疗工伤期间的工资福利由用人单位支付", "生育保险费由用人单位和职工个人按比例共同缴纳", "城镇居民基本医疗保险实行个人缴费和政府补贴相结合", "失业人员领取失业保险金的期限与失业保险费的累计缴费时间有关"], "answer": ["B"], "explain": "逐项判断：A治疗工伤期间的工资福利由用人单位支付，符合第三十九条，正确；B生育保险费由用人单位按规定缴纳、职工不缴纳，并非“单位和职工个人按比例共同缴纳”，说法错误；C城镇居民基本医疗保险实行个人缴费和政府补贴相结合，符合第二十五条，正确；D领取失业保险金期限与累计缴费时间挂钩（满1年不足5年最长12个月，满5年不足10年最长18个月，10年以上最长24个月），符合第四十六条，正确", "tip": "易错点：误以为生育保险由单位和职工共同缴纳；记忆要点：生育保险费由用人单位缴纳，职工个人不缴纳。", "key": "真题演练：B", "from": "第 2 期 · 本周常识"}, {"date": "2026-10-31", "src": "xc", "no": 3, "mod": "数量关系", "type": "single", "stem": "只有在星期六，小王才会去图书馆。如果某年3月小王一共有5天去过图书馆，则当年4月1日可能是（ ）。", "options": ["星期二", "星期三", "星期五", "星期六"], "answer": ["A"], "explain": "思路：星期日期枚举。详解：每连续28天必有4个周六，3月共31天，多出3天（29、30、31日），要出现5个周六，这3天里必须恰有1个周六。分三种：若3月29日是周六，则4月1日为星期二；若3月30日是周六，则4月1日为星期一；若3月31日是周六，则4月1日为星期日。选项中只有星期二符合。故答案为A。", "tip": "易错点：3月31天比28天多3天，忘了这多出的3天里必须再含1个周六才能凑够5个周六。", "key": "思路：星期日期枚举。详解：每连续28天必有4个周六，3月共31天，多出3天（29", "from": "第 3 批 · 行测加练"}, {"date": "2026-10-26", "src": "issue", "no": 4, "mod": "常识判断", "type": "single", "stem": "根据《中华人民共和国行政许可法》，下列说法不正确的是：", "options": ["行政机关实施行政许可，不得收取任何费用", "行政许可申请可以通过电子数据交换和电子邮件等方式提出", "被许可人出借行政许可证件的，行政机关应当依法给予行政处罚；构成犯罪的，依法追究刑事责任", "当申请人的申请事项不属于本行政机关职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请"], "answer": ["A"], "explain": "逐项判断：A行政机关实施行政许可不得收取任何费用，说法错误——依照法律、行政法规收取费用的，应按公布的法定项目和标准收费，所收费用全部上缴国库；B申请可通过信函、电报、电传、传真、电子数据交换和电子邮件等方式提出，符合第二十九条，正确；C被许可人涂改、倒卖、出租、出借行政许可证件应受行政处罚直至追究刑责，符合第八十条，正确；D申请事项不属本机关职权范围应即时作出不予受理决定并告知向有关机关申请，符合第三十二条，正确", "tip": "易错点：误以为行政许可一律不得收费；记忆要点：法律、行政法规另有规定的可按公布标准收费，并非“不得收取任何费用”。", "key": "真题演练：A", "from": "第 4 期 · 本周常识"}, {"date": "2026-10-26", "src": "issue", "no": 5, "mod": "常识判断", "type": "single", "stem": "下列实验与其贡献的对应关系，不正确的是：", "options": ["马德堡半球实验——证明了大气压的存在", "孟德尔的豌豆杂交实验——发现了遗传规律", "傅科钟摆实验——验证了万有引力定律的正确性", "牛顿的棱镜分解太阳光实验——发现太阳光是一种复色光"], "answer": ["C"], "explain": "逐项判断：A马德堡半球实验（1654年格里克）证明大气压存在且强大，对应正确；B孟德尔豌豆杂交实验发现遗传规律（分离定律、自由组合定律），对应正确；C傅科钟摆实验（1851年）证明的是地球自转，验证万有引力定律并测出引力常量的是卡文迪许扭秤实验（1789年），对应错误；D牛顿三棱镜分解太阳光实验证明太阳光是复色光，对应正确", "tip": "易错点：把傅科钟摆实验的结论记成验证万有引力；记忆要点：傅科摆证明地球自转，卡文迪许扭秤才验证万有引力并测出引力常量。", "key": "真题演练：C", "from": "第 5 期 · 本周常识"}, {"date": "2026-10-30", "src": "xc", "no": 6, "mod": "数量关系", "type": "single", "stem": "公司研发部门共5名员工，年龄各不相同，其中年龄最大的比最小的大10岁。某年，年龄最大的2人年龄之和是最小的2人年龄之和的1.25倍；2年后，除年龄排名居中的1人外其余4人年龄之和为125岁。那么再过2年，年龄排名第三的员工最大可能为多少岁？", "options": ["33", "34", "35", "36"], "answer": ["C"], "explain": "思路：方程加最值构造；详解：设某年5人年龄从大到小a>b>c>d>e。a+b=1.25(d+e)①；2年后其余4人（除居中c）年龄和=125，即当年(a+b+d+e)=125-4×2=117②。联立：a+b=1.25(d+e)且a+b+d+e=117，得2.25(d+e)=117，d+e=52，a+b=65。要c最大：因b<a且年龄不同，b最大取32（a=33），则c=b-1=31；此时e=a-10=23，d=52-23=29，顺序33>32>31>29>23成立。问“再过2年”（距那年共4年），c=31+4=35岁。故答案为C。", "tip": "易错点：“再过2年”与“2年后”时间节点算错；求第三大年龄最大值要让其他年龄尽量极端。", "key": "思路：方程加最值构造；详解：设某年5人年龄从大到小a>b>c>d>e。a+b=1", "from": "第 6 批 · 行测加练"}, {"date": "2026-10-26", "src": "xc", "no": 7, "mod": "科学推理", "type": "single", "stem": "小李驾驶卡丁车驶过一个半圆形弯道时，滑离了原定赛道，撞到了安全护栏。为了避免卡丁车转弯时滑离赛道，下列做法最可能有效的是：", "options": ["增加卡丁车的质量", "减少卡丁车的质量", "使用更加粗糙的轮胎", "减小半圆形弯道的半径"], "answer": ["C"], "explain": "思路：转弯靠静摩擦力提供向心力，不侧滑需μmg≥mv²/r；详解：质量m在两边约掉，增减质量无效；减小半径r会让临界速度更低、更易滑；换更粗糙轮胎增大μ，可提高临界速度。故答案为C。", "tip": "易错点：以为增减质量能防滑；向心力mv²/r与最大摩擦力μmg都含m，质量会约掉，临界速度v=√(μg r)与质量无关。", "key": "思路：转弯靠静摩擦力提供向心力，不侧滑需μmg≥mv²/r；详解：质量m在两边约", "from": "第 7 批 · 行测加练"}, {"date": "2026-10-31", "src": "idiom", "no": 8, "mod": "言语理解与表达", "type": "single", "stem": "父母对孩子____，反害了他。", "options": ["孤立无援", "马革裹尸", "家喻户晓", "百依百顺"], "answer": ["D"], "explain": "依、顺：顺从。什么都依从，形容一味顺从", "tip": "多含贬义，指盲目迁就", "key": "成语填空：百依百顺", "from": "第 8 期 · 词语速记"}, {"date": "2026-10-26", "src": "issue", "no": 9, "mod": "常识判断", "type": "single", "stem": "嘉兴南湖革命纪念馆的题诗\"革命声传画舫中，诞生共党庆工农\"纪念的历史事件是：", "options": ["中共一大的召开", "第一次国共合作", "中共工农红军的组建", "第一次全国劳动大会的召开"], "answer": ["A"], "explain": "逐项判断：A正确，1964年董必武为嘉兴南湖题诗\"革命声传画舫中，诞生共党庆工农\"，纪念1921年中共一大在南湖游船上闭幕、标志中国共产党成立；B第一次国共合作形成于1924年国民党一大（广州）；C工农红军1928年正式定名；D第一次全国劳动大会1922年在广州召开", "tip": "易错点：看到\"诞生共党\"误以为是建党，但忽略画舫（南湖红船）对应的具体会议；记忆要点：嘉兴南湖红船是中共一大闭幕地。", "key": "真题演练：A", "from": "第 9 期 · 本周常识"}, {"date": "2026-10-26", "src": "issue", "no": 10, "mod": "常识判断", "type": "single", "stem": "《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》提出，推进国家安全体系和能力现代化，建设更高水平平安中国。下列有关说法正确的是（ ）。", "options": ["锻造实战实用的国家安全能力，把捍卫国土安全摆在首位", "统筹推进房地产、地方政府债务、中小金融机构等风险有序化解", "健全国家安全体系，坚持以风险防控为先导、法治保障为落脚点", "完善公共安全体系，推动公共安全治理模式由事后处理向事中控制转型"], "answer": ["B"], "explain": "逐项判断：A错误，《建议》提出锻造实战实用的国家安全能力，把捍卫政治安全摆在首位，不是国土安全；B正确，要提高防范化解重点领域风险能力，统筹推进房地产、地方政府债务、中小金融机构等风险有序化解，严防系统性风险；C错误，健全国家安全体系应坚持以战略为先导、政策为抓手、法治为保障、风险防控为落脚点，选项把先导与落脚点互换；D错误，公共安全治理模式向事前预防转型，不是由事后向事中", "tip": "易错点：A把'政治安全'首位误记成'国土安全'、C把'战略为先导、风险防控为落脚点'互换、D把'事前预防'误记成'事中控", "key": "真题演练：B", "from": "第 10 期 · 本周常识"}, {"date": "2026-10-31", "src": "issue", "no": 11, "mod": "常识判断", "type": "single", "stem": "如图所示，物体A在F的作用下静止在物体B的斜面上，物体B始终静止在水平面上，如果物体B的斜面完全光滑，则下列说法正确的是（ ）。", "options": ["物体B总共受到3个力的作用", "物体B受到的摩擦力的大小等于F", "物体A对物体B的作用力大小为F", "物体A与物体B的相互作用力大小不等"], "answer": ["B"], "explain": "思路：整体法+隔离法", "tip": "易错点：忽略整体法，误以为地面对B无摩擦力；或误以为A、B间有摩擦力（因斜面光滑）；记忆要点：斜面光滑则A、B间无摩擦，", "key": "真题演练：B", "from": "第 11 期 · 本周常识"}, {"date": "2026-10-30", "src": "xc", "no": 12, "mod": "判断推理", "type": "single", "stem": "有人认为，短视频时代的到来并不会减少好友相互交流的时间，因为不喜欢社交的人即使在没有短视频可以“刷”的时候也不会增加与人交流的时间。 下列选项所犯的逻辑错误与题干最相似的是（ ）。", "options": ["即便不打击犯罪，遵纪守法的人依旧很多，所以犯罪行为并不会影响人们遵纪守法", "某个地方节约水资源意义不大，因为无论怎样加大节约力度，世界上也会有严重缺水的地区", "不喜欢赚钱的人即使不买奢侈品也不会成为富翁，因此，购买奢侈品并不会妨碍人们成为富翁", "课外活动不会影响好学生的成绩，因为喜欢学习的人即使参加了课外活动也不会减少自己学习文化课的时间"], "answer": ["C"], "explain": "题干错误：A（短视频）不影响B（交流时间），因为没有A时也不影响B。即从'无A无B变化'推出'有A也无B变化'。C：A（买奢侈品）不影响B（成富翁），因为没有A时不喜欢赚钱的人也不会成富翁，结构一致。D是'有A也不影响B'，方向相反。故正确答案为C。", "tip": "易错点：易误选D，因为都是'A不影响B，因为喜欢X的人怎样'；但题干是'没有A也不影响B'，D是'有A也不影响B'。", "key": "题干错误：A（短视频）不影响B（交流时间），因为没有A时也不影响B。即从'无A无", "from": "第 12 批 · 行测加练"}], "sl": [{"no": 1, "mod": "综合分析", "from": "申论真题 · 国考", "stem": "【真题材料摘要】G市工业大学冯教授团队入驻桃李镇清池村，以「与村民一起动手」代替授课，从建大椅子、家庭美术馆起步，重新挖掘「烧奔塔」「成人礼」等传统习俗，举办乡村时装秀。主张以「膜拜」而非「治理教导」的心态介入乡村，探索「超越艺术」的路径，当好挖掘本土文化特色的「运营官」。；N市隆金公司专注汽车门把手等配件，2012年起每年投入数千万元建设全自动数字化车间，依托企业研究院、海外研发中心、产学研合作吸引创新人才，近三年完成研发项目超300项、专利295项，95%产品实现国产化替代，迈入「单项冠军」方阵。；J省江平县曾面临乡镇卫生院人才奇缺困境，通过稳定现有人才、绩效考核拉开收入差距、急缺人才现场考试招录、购房补贴、偏远乡镇补助、编制周转池、县管乡用乡管村用、实训基地轮训、与三甲医院共建院士工作站和远程会诊中心等举措破解基层医疗人才难题。；S市涌现一批公共文化空间：畅雅艺术空间辐射6200居民、活动火爆；但不少民营美术馆、24小时书院冷冷清清；大型实体书店场景营造同质化、审美疲劳；市美术馆被当「网红打卡点」；同时存在载体规模偏小、布局分散、缺少主题型创意型空间等问题。；某大学图书馆王师傅以桌椅维修为主的木工工作，修抽屉、做木门、为古籍定制木箱、打磨卡窗户的小木块，在修缮中创造、于毫末处耕耘，为师生温暖笃定的生活秩序默默付出，展现平凡岗位的工匠精神。\n「给定资料2」中，隆金公司虽然做的是配件，但也成为了市场中的主角。请你谈谈隆金公司为什么能成为「市场中的主角」。要求：紧扣资料、归纳准确；内容全面、条理清晰，不超过 300 字。", "req": "「给定资料2」中，隆金公司虽然做的是配件，但也成为了市场中的主角。请你谈谈隆金公司为什么能成为「市场中的主角」。要求：紧扣资料、归纳准确；内容全面、条理清晰，不超过 300 字。", "limit": "不超过300字", "points": [{"pt": "隆金公司成为市场主角的原因：①长期专注配件研发生产，以严格质量控制和持续技术创新把门把手等配件做到行业顶尖", "n": 3}, {"pt": "不断拓展高端、新能源、国际市场，紧跟行业趋势，通过研发创新与技术迭代提升竞争力", "n": 3}, {"pt": "注重产学研合作，依托企业研究院、博士后工作站等平台引进培养人才", "n": 3}, {"pt": "精准把握市场脉搏，针对新能源汽车等新兴领域前瞻布局，奠定发展基础。", "n": 3}], "sample": "隆金公司成为市场主角的原因：①长期专注配件研发生产，以严格质量控制和持续技术创新把门把手等配件做到行业顶尖；②不断拓展高端、新能源、国际市场，紧跟行业趋势，通过研发创新与技术迭代提升竞争力；③注重产学研合作，依托企业研究院、博士后工作站等平台引进培养人才；④精准把握市场脉搏，针对新能源汽车等新兴领域前瞻布局，奠定发展基础。", "tip": "综合分析题：先分层再压缩，每条“总括句＋具体做法”，不超字数、不漏分值点。"}, {"no": 2, "mod": "概括归纳", "from": "申论真题 · 广东省考", "stem": "【真题材料摘要】梳理习近平总书记关于新质生产力的一系列重要论述（2023年首次提出、2024年系统阐释概念内涵、党的二十届三中全会强调支持全面创新体制机制）。广东连续三年新春首个工作日召开全省高质量发展大会，坚持实体经济为本、制造业当家，推动产业科技互促双强。；2024年广东GDP迈上14万亿元新台阶、连续36年全国首位，区域创新能力连续8年全国第一；拥有全部31个制造业大类，15个行业规模全国第一；研发人员超150万居全国首位；实施百万英才汇南粤计划；粤港澳大湾区建设纵深推进，成为高质量发展示范地。；广东以建设大湾区国际科创中心和综合性国家科学中心为牵引，构建「基础研究+技术攻关+成果转化+科技金融+人才支撑」全过程创新链；鹏城、广州实验室引领多层次实验室体系；散裂中子源等大科学装置落地；在人工智能、机器人等领域集中发力，打好关键核心技术攻关战。；S市约90%科研机构、科研人员、研发经费、发明专利申请来源于企业：政策制定征求企业意见成「规定动作」；健全以企业研发投入为主的多元投入体系（企业占比93.3%）；银行建立科技型企业全生命周期金融服务机制；推行「企业出题、研究院遴选、高校揭榜」的科研组织模式；R镇出台以企业为主体的产学研专项政策。；G市科技局组织专家学者研讨科研成果转化：科研人员不了解产业需求、成果与产业脱节；高校以论文发表为主要评价标准、转化权重低；科研人员收益比例低、限制多、怕风险；技术经理人队伍数量不足素质不高；政策落地慢、高校未出台实施办法等。；传统产业以数智技术、绿色技术赋能「老树发新芽」；新兴产业（低空经济、智能机器人、新能源）不断突破——全国每3台工业机器人一台广东造、新能源汽车产量占全国四分之一；未来产业瞄准七大领域实施七大工程；深圳垃圾焚烧发电厂变生态园、阳江海上风电、湛江氢基竖炉等绿色实践。\n请根据材料 4，概括 S 市强化企业科技创新主体地位的主要做法。要求：概括全面、准确，条理清晰，篇幅不超过 200 字。", "req": "请根据材料 4，概括 S 市强化企业科技创新主体地位的主要做法。要求：概括全面、准确，条理清晰，篇幅不超过 200 字。", "limit": "不超过300字", "points": [{"pt": "主要做法：①尊重企业意见——召开发展座谈会邀请企业发言，政策征求企业意见，提升企业话语权", "n": 4}, {"pt": "加强研发投入——健全以企业研发投入为主的多元科技创新投入体系", "n": 4}, {"pt": "提供金融服务——建立科技型企业全生命周期金融服务机制，提供多元化接力式金融服务", "n": 4}, {"pt": "创新组织模式——构建以企业为主体的科研组织体系，建立「企业出题、研究院遴选、高校揭榜」工作机制", "n": 4}, {"pt": "推动成果转化——出台产学研专项政策，搭建平台聚合企业需求，打通产学研融合最后一公里。", "n": 4}], "sample": "主要做法：①尊重企业意见——召开发展座谈会邀请企业发言，政策征求企业意见，提升企业话语权；②加强研发投入——健全以企业研发投入为主的多元科技创新投入体系；③提供金融服务——建立科技型企业全生命周期金融服务机制，提供多元化接力式金融服务；④创新组织模式——构建以企业为主体的科研组织体系，建立「企业出题、研究院遴选、高校揭榜」工作机制；⑤推动成果转化——出台产学研专项政策，搭建平台聚合企业需求，打通产学研融合最后一公里。", "tip": "归纳概括题：先分层再压缩，每条“总括句＋具体做法”，不超字数、不漏分值点。"}]}];
